"""The drawing kit for the word pictures (#332): flat shapes with an ink outline, faceless figures (owner, 27 Oct 2026), the
carousels' colours, and a gentle loop on each picture that eases in and out (MOTION-STYLE.md). Every picture is a 200 x 200 SVG
with its own small <style>, so it animates as a plain <img> and stops for people who ask for reduced motion.

A primitive returns an SVG fragment at absolute coordinates. Anything that animates is wrapped as A('<class>', fragment), never
given a transform attribute of its own, because a CSS animation replaces an element's transform."""

INK = "#17262B"
O = f'stroke="{INK}" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"'
T = f'stroke="{INK}" stroke-width="3.5" stroke-linejoin="round" stroke-linecap="round"'      # a thinner line for small parts
SKIN = ["#e8c4a6", "#c48f66", "#8d5f3e", "#d9b08c", "#a8784f"]
RED, ORANGE, YELLOW, GREEN, TEAL, BLUE, PURPLE, PINK, BROWN, GREY, WHITE, CREAM, GOLD = (
    "#E8574B", "#FF9F45", "#FFC93C", "#5DBB63", "#2E7263", "#4D96FF", "#9B6BFF", "#F49AC1", "#9C6B3E", "#B8C2C8", "#FFFFFF", "#FFF8EC", "#E9B949")
BG = {"food": "#FFE9D9", "animal": "#E2F2D8", "nature": "#DDEFFC", "body": "#FDE3E6", "home": "#F3E7D8", "place": "#E7E6FB",
      "study": "#FFF2C2", "thing": "#E4EEF2", "people": "#F6E3F6", "faith": "#E2F1E8", "number": "#FFEFD6", "time": "#E1EAFE",
      "verb": "#FFE6EE", "word": "#EEF0E2"}

KEY = {   # one loop per class; transform-box keeps each origin on the shape itself
    "b": "@keyframes b{50%{transform:translateY(-7px)}}.b{animation:b 2.6s ease-in-out infinite}",
    "s": "@keyframes s{0%,100%{transform:rotate(-6deg)}50%{transform:rotate(6deg)}}.s{transform-box:fill-box;transform-origin:50% 100%;animation:s 3s ease-in-out infinite}",
    "st": "@keyframes st{0%,100%{transform:rotate(-7deg)}50%{transform:rotate(7deg)}}.st{transform-box:fill-box;transform-origin:50% 0%;animation:st 2.6s ease-in-out infinite}",
    "p": "@keyframes p{50%{transform:scale(1.1)}}.p{transform-box:fill-box;transform-origin:50% 50%;animation:p 1.9s ease-in-out infinite}",
    "r": "@keyframes r{0%{opacity:0;transform:translateY(10px)}40%{opacity:1}100%{opacity:0;transform:translateY(-18px)}}.r{animation:r 2.6s ease-in-out infinite}",
    "f": "@keyframes f{0%{opacity:0;transform:translateY(-16px)}25%{opacity:1}100%{opacity:0;transform:translateY(26px)}}.f{animation:f 1.7s ease-in infinite}",
    "t": "@keyframes t{to{transform:rotate(360deg)}}.t{transform-box:fill-box;transform-origin:50% 50%;animation:t 9s ease-in-out infinite}",
    "w": "@keyframes w{from{transform:rotate(-16deg)}to{transform:rotate(16deg)}}.w{transform-box:fill-box;transform-origin:0% 100%;animation:w 1.1s ease-in-out infinite alternate}",
    "wr": "@keyframes wr{from{transform:rotate(16deg)}to{transform:rotate(-16deg)}}.wr{transform-box:fill-box;transform-origin:100% 100%;animation:wr 1.1s ease-in-out infinite alternate}",
    "x": "@keyframes x{50%{transform:translateX(12px)}}.x{animation:x 2.8s ease-in-out infinite}",
    "xl": "@keyframes xl{50%{transform:translateX(-12px)}}.xl{animation:xl 2.8s ease-in-out infinite}",
    "k": "@keyframes k{to{transform:scaleY(.5)}}.k{transform-box:fill-box;transform-origin:50% 100%;animation:k .55s ease-in-out infinite alternate}",
    "g": "@keyframes g{50%{opacity:.25}}.g{animation:g 2.2s ease-in-out infinite}",
    "j": "@keyframes j{0%,70%,100%{transform:rotate(0)}76%{transform:rotate(-9deg)}82%{transform:rotate(9deg)}88%{transform:rotate(-5deg)}94%{transform:rotate(3deg)}}.j{transform-box:fill-box;transform-origin:50% 50%;animation:j 2.4s ease-in-out infinite}",
    "h": "@keyframes h{0%,100%{transform:translateY(0)}50%{transform:translateY(-24px)}}.h{animation:h 1.5s cubic-bezier(.45,0,.55,1) infinite}",
    "u": "@keyframes u{0%,100%{transform:translateY(8px)}50%{transform:translateY(-8px)}}.u{animation:u 3.2s ease-in-out infinite}",
    "z": "@keyframes z{0%{transform:scale(.6);opacity:0}30%{opacity:1}100%{transform:scale(1.25);opacity:0}}.z{transform-box:fill-box;transform-origin:50% 50%;animation:z 2.2s ease-out infinite}",
    "c": "@keyframes c{50%{transform:rotate(-24deg)}}.c{transform-box:fill-box;transform-origin:20% 80%;animation:c 2.4s ease-in-out infinite}",
}
D = {1: "animation-delay:.6s", 2: "animation-delay:1.2s", 3: "animation-delay:1.8s"}

def A(cls, inner, d=None, origin=None):
    style = ";".join(x for x in (D.get(d, ""), f"transform-origin:{origin}" if origin else "") if x)
    return f'<g class="{cls}"' + (f' style="{style}"' if style else "") + f'>{inner}</g>'

def svg(inner, bg="thing"):
    """A scene (a sky colour, or a background name ending in *) is cut to the circle; everything else may break out of it."""
    clip = bg.startswith("#") or bg.endswith("*"); bg = bg.rstrip("*")
    used = sorted({c for c in KEY if f'class="{c}"' in inner})
    css = "".join(KEY[c] for c in used) + "@media (prefers-reduced-motion:reduce){*{animation:none!important}}"
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" width="200" height="200"><style>{css}</style>'
            + ('<clipPath id="k"><circle cx="100" cy="100" r="94"/></clipPath>' if clip else "") +
            f'<circle cx="100" cy="100" r="94" fill="{BG.get(bg, bg)}"/><g class="c"' + (' clip-path="url(#k)"' if clip else "") + f'>{inner}</g></svg>')

# ---- shapes ------------------------------------------------------------------------------------------------------------------
def mini(inner, x, y, s): return f'<g transform="translate({x},{y}) scale({s}) translate(-100,-100)">{inner}</g>'
def circ(x, y, r, fill, o=O): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{fill}" {o}/>'
def ell(x, y, rx, ry, fill, o=O, rot=0): return f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}" fill="{fill}" {o}' + (f' transform="rotate({rot} {x} {y})"' if rot else "") + '/>'
def rect(x, y, w, h, fill, rx=8, o=O): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill}" {o}/>'
def path(d, fill="none", o=O): return f'<path d="{d}" fill="{fill}" {o}/>'
def line(x1, y1, x2, y2, o=O): return f'<path d="M{x1} {y1}L{x2} {y2}" fill="none" {o}/>'
def text(x, y, s, size=40, fill=INK, font="Arial, Helvetica, sans-serif", weight=700, anchor="middle"):
    return f'<text x="{x}" y="{y}" text-anchor="{anchor}" font-family="{font}" font-weight="{weight}" font-size="{size}" fill="{fill}">{s}</text>'
def ar(x, y, s, size=56, fill=INK):   # Arabic, in the app's Arabic font when it's installed
    return f'<text x="{x}" y="{y}" text-anchor="middle" direction="rtl" font-family="IBM Plex Sans Arabic, Amiri, Arial" font-weight="700" font-size="{size}" fill="{fill}">{s}</text>'
def star(x, y, r, fill=YELLOW, o=O):
    import math
    pts = " ".join(f"{x + (r if i % 2 == 0 else r * .45) * math.sin(math.pi * i / 5):.1f},{y - (r if i % 2 == 0 else r * .45) * math.cos(math.pi * i / 5):.1f}" for i in range(10))
    return f'<polygon points="{pts}" fill="{fill}" {o}/>'
def spark(x, y, r=10, fill=YELLOW):
    return path(f"M{x} {y - r}Q{x + r * .2} {y - r * .2} {x + r} {y}Q{x + r * .2} {y + r * .2} {x} {y + r}Q{x - r * .2} {y + r * .2} {x - r} {y}Q{x - r * .2} {y - r * .2} {x} {y - r}Z", fill, T)
def sparks(*pts): return "".join(A("g", spark(x, y, r), d=i % 4) for i, (x, y, r) in enumerate(pts))
def arrow(x1, y1, x2, y2, fill=INK, w=7):
    import math
    a = math.atan2(y2 - y1, x2 - x1); hx, hy = x2 - 14 * math.cos(a), y2 - 14 * math.sin(a)
    l, r = (hx + 10 * math.cos(a + math.pi / 2), hy + 10 * math.sin(a + math.pi / 2)), (hx + 10 * math.cos(a - math.pi / 2), hy + 10 * math.sin(a - math.pi / 2))
    return (f'<path d="M{x1} {y1}L{hx:.1f} {hy:.1f}" stroke="{fill}" stroke-width="{w}" stroke-linecap="round" fill="none"/>'
            f'<path d="M{x2} {y2}L{l[0]:.1f} {l[1]:.1f}L{r[0]:.1f} {r[1]:.1f}Z" fill="{fill}" stroke="{fill}" stroke-width="3" stroke-linejoin="round"/>')
def steam(x, y, n=3, gap=16):
    return "".join(A("r", path(f"M{x + (i - (n - 1) / 2) * gap} {y}c-8-10 8-16 0-28", "none", f'stroke="{INK}" stroke-width="4" stroke-linecap="round" opacity=".55"'), d=i) for i in range(n))
def zzz(x, y): return "".join(A("r", text(x + i * 14, y - i * 14, "z", 22 + i * 6), d=i) for i in range(3))
def waves(x, y, n=3, s=1.0):   # sound waves to the right of (x, y)
    return "".join(A("g", path(f"M{x + 10 + i * 13 * s} {y - (12 + i * 9) * s}q{12 * s} {(12 + i * 9) * s} 0 {(24 + i * 18) * s}", "none", O), d=i) for i in range(n))
def bubble(x, y, w, h, fill=WHITE, tail="left"):
    tx = x + 18 if tail == "left" else x + w - 18
    return (rect(x, y, w, h, fill, 18) + path(f"M{tx - 8} {y + h - 3}L{tx - 14 if tail == 'left' else tx + 14} {y + h + 16}L{tx + 8} {y + h - 3}", fill, O)
            + f'<path d="M{tx - 7} {y + h - 2.5}L{tx + 7} {y + h - 2.5}" stroke="{fill}" stroke-width="6"/>')
def thought(x, y, w, h, fill=WHITE):
    return rect(x, y, w, h, fill, h / 2) + circ(x + 14, y + h + 12, 7, fill) + circ(x + 4, y + h + 26, 4.5, fill)

# ---- people: faceless, flat, as in the carousels (feet at y) -----------------------------------------------------------------
def person(x, y, s=1.0, skin=SKIN[1], top=None, body=BLUE, arm=None, beard=None, legs=True, cls=None, prop=""):
    """top: 'kufi', 'hijab:<c>', 'hair:<c>', 'cap:<c>', 'helmet:<c>', 'grey'; arm: 'wave', 'fold', 'point', 'up', 'out', 'book:<c>', 'hold'."""
    g = ""
    if legs: g += f'<rect x="-28" y="-70" width="22" height="70" rx="10" fill="{INK}"/><rect x="6" y="-70" width="22" height="70" rx="10" fill="{INK}"/>'
    g += path("M-46 -60L-36 -168Q0 -190 36 -168L46 -60Z", body)
    if top and top.startswith("hijab"):
        c = top.split(":")[1]
        g += path("M0 -262C-40 -262 -52 -220 -48 -190C-46 -168 -52 -150 -40 -136L40 -136C52 -150 46 -168 48 -190C52 -220 40 -262 0 -262Z", c)
        g += ell(0, -206, 28, 34, skin)
    else:
        g += circ(0, -210, 36, skin)
        if beard: g += path("M-26 -196C-24 -168 24 -168 26 -196C14 -184 -14 -184 -26 -196Z", beard)
        if top == "kufi": g += path("M-34 -222C-32 -254 32 -254 34 -222Z", WHITE)
        elif top == "grey": g += path("M-36 -214C-40 -256 40 -256 36 -214C24 -232 -24 -232 -36 -214Z", "#D9DEE2")
        elif top and top.startswith("hair"): g += path("M-36 -214C-40 -256 40 -256 36 -214C24 -232 -24 -232 -36 -214Z", top.split(":")[1])
        elif top and top.startswith("cap"): g += path("M-36 -222C-34 -258 34 -258 36 -222Z", top.split(":")[1]) + path("M-6 -224L60 -222L58 -212L-4 -214Z", top.split(":")[1])
        elif top and top.startswith("helmet"): g += path("M-40 -214C-40 -262 40 -262 40 -214Z", top.split(":")[1]) + rect(-46, -220, 92, 10, top.split(":")[1], 5)
    if arm == "wave": g += A("w", path("M36 -150C66 -170 70 -200 62 -222", "none", f'stroke="{body}" stroke-width="20" stroke-linecap="round"') + circ(62, -228, 12, skin))
    elif arm == "fold": g += path("M-34 -138C-14 -112 14 -112 34 -138", "none", f'stroke="{body}" stroke-width="20" stroke-linecap="round"') + ell(0, -122, 16, 10, skin)
    elif arm == "point": g += path("M36 -148L84 -150", "none", f'stroke="{body}" stroke-width="20" stroke-linecap="round"') + circ(90, -150, 11, skin)
    elif arm == "up": g += path("M-36 -150C-60 -180 -60 -206 -54 -228M36 -150C60 -180 60 -206 54 -228", "none", f'stroke="{body}" stroke-width="20" stroke-linecap="round"') + circ(-54, -234, 11, skin) + circ(54, -234, 11, skin)
    elif arm == "out": g += path("M36 -150C60 -140 72 -120 80 -106", "none", f'stroke="{body}" stroke-width="20" stroke-linecap="round"') + circ(84, -100, 11, skin)
    elif arm == "hold": g += path("M-34 -140C-10 -120 20 -116 44 -124", "none", f'stroke="{body}" stroke-width="20" stroke-linecap="round"') + circ(50, -126, 11, skin)
    elif arm and arm.startswith("book"):
        g += path("M-34 -138C-14 -112 14 -112 34 -138", "none", f'stroke="{body}" stroke-width="20" stroke-linecap="round"')
        g += path("M-32 -140L0 -128L32 -140L32 -100L0 -88L-32 -100Z", arm.split(":")[1]) + line(0, -128, 0, -88, T)
    g += prop
    inner = A(cls, g) if cls else g
    return f'<g transform="translate({x},{y}) scale({s})">{inner}</g>'
def man(x, y, s=.62, **k): return person(x, y, s, k.pop("skin", SKIN[1]), k.pop("top", "kufi"), k.pop("body", TEAL), beard=k.pop("beard", "#2a1d14"), **k)
def woman(x, y, s=.62, **k): return person(x, y, s, k.pop("skin", SKIN[3]), k.pop("top", "hijab:#9B6BFF"), k.pop("body", PINK), **k)
def boy(x, y, s=.46, **k): return person(x, y, s, k.pop("skin", SKIN[0]), k.pop("top", "hair:#3a2a1c"), k.pop("body", ORANGE), **k)
def girl(x, y, s=.46, **k): return person(x, y, s, k.pop("skin", SKIN[2]), k.pop("top", "hijab:#2EB67D"), k.pop("body", YELLOW), **k)
def oldman(x, y, s=.6, **k): return person(x, y, s, k.pop("skin", SKIN[3]), "grey", k.pop("body", BROWN), beard="#E6E6E6", **k) + line(x + 40 * s, y - 120 * s, x + 50 * s, y, f'stroke="{BROWN}" stroke-width="7" stroke-linecap="round"')
def oldwoman(x, y, s=.6, **k): return person(x, y, s, k.pop("skin", SKIN[0]), "hijab:#E9E4DA", k.pop("body", PURPLE), **k) + line(x + 40 * s, y - 120 * s, x + 50 * s, y, f'stroke="{BROWN}" stroke-width="7" stroke-linecap="round"')
def baby(x, y, s=.4): return f'<g transform="translate({x},{y}) scale({s})">' + ell(0, -60, 50, 56, "#CFE5FF") + circ(0, -136, 34, SKIN[0]) + "</g>"

# ---- food --------------------------------------------------------------------------------------------------------------------
def plate(x=100, y=140, rx=70, ry=20): return ell(x, y, rx, ry, WHITE) + ell(x, y - 2, rx * .65, ry * .55, "#F1F1F1", T)
def bowl(x=100, y=120, w=120, fill=WHITE, inside=None):
    s = path(f"M{x - w / 2} {y}Q{x - w / 2} {y + w * .55} {x} {y + w * .55}Q{x + w / 2} {y + w * .55} {x + w / 2} {y}Z", fill)
    return (ell(x, y, w / 2, w * .12, inside) if inside else "") + s
def glass(x=100, y=165, h=90, w=56, fill="#9fd8ff", level=.7):
    return (path(f"M{x - w / 2 + 3} {y - h * level}L{x + w / 2 - 3} {y - h * level}L{x + w / 2 - 8} {y}L{x - w / 2 + 8} {y}Z", fill, "") +
            path(f"M{x - w / 2} {y - h}L{x + w / 2} {y - h}L{x + w / 2 - 8} {y}L{x - w / 2 + 8} {y}Z") + line(x - w / 2 + 12, y - h + 12, x - w / 2 + 16, y - 16, f'stroke="#fff" stroke-width="6" stroke-linecap="round" opacity=".7"'))
def cup(x=100, y=160, fill=WHITE, drink=BROWN):
    return (path(f"M{x - 42} {y - 64}L{x + 42} {y - 64}L{x + 34} {y}L{x - 34} {y}Z", fill) + path(f"M{x + 38} {y - 50}C{x + 66} {y - 50} {x + 66} {y - 16} {x + 34} {y - 16}") +
            ell(x, y - 64, 42, 8, drink) + ell(x, y + 4, 56, 10, fill))
def teaglass(x=100, y=160):
    return ell(x, y + 6, 54, 11, WHITE) + path(f"M{x - 26} {y - 80}C{x - 36} {y - 40} {x - 18} {y - 30} {x - 22} {y}L{x + 22} {y}C{x + 18} {y - 30} {x + 36} {y - 40} {x + 26} {y - 80}Z", "#C8551F") + path(f"M{x - 26} {y - 80}L{x + 26} {y - 80}", "none")
def fruit(x, y, r, fill, leaf=GREEN, stem=True):
    return circ(x, y, r, fill) + (line(x, y - r, x + 3, y - r - 12) if stem else "") + (path(f"M{x + 3} {y - r - 6}C{x + 18} {y - r - 20} {x + 30} {y - r - 8} {x + 22} {y - r}C{x + 14} {y - r + 4} {x + 6} {y - r} {x + 3} {y - r - 6}Z", leaf) if leaf else "")
def apple(x=100, y=112, s=1): return path(f"M{x} {y - 40 * s}C{x - 30 * s} {y - 58 * s} {x - 60 * s} {y - 30 * s} {x - 54 * s} {y + 6 * s}C{x - 48 * s} {y + 40 * s} {x - 20 * s} {y + 52 * s} {x} {y + 40 * s}C{x + 20 * s} {y + 52 * s} {x + 48 * s} {y + 40 * s} {x + 54 * s} {y + 6 * s}C{x + 60 * s} {y - 30 * s} {x + 30 * s} {y - 58 * s} {x} {y - 40 * s}Z", RED) + line(x, y - 40 * s, x + 4 * s, y - 62 * s) + path(f"M{x + 4 * s} {y - 54 * s}C{x + 20 * s} {y - 72 * s} {x + 36 * s} {y - 60 * s} {x + 30 * s} {y - 50 * s}C{x + 22 * s} {y - 44 * s} {x + 10 * s} {y - 48 * s} {x + 4 * s} {y - 54 * s}Z", GREEN)
def pear(x=100, y=118): return path(f"M{x} {y - 56}C{x - 18} {y - 56} {x - 20} {y - 24} {x - 30} {y - 8}C{x - 54} {y + 24} {x - 34} {y + 52} {x} {y + 52}C{x + 34} {y + 52} {x + 54} {y + 24} {x + 30} {y - 8}C{x + 20} {y - 24} {x + 18} {y - 56} {x} {y - 56}Z", "#C6D84E") + line(x, y - 56, x + 4, y - 74)
def banana_peel(x=100, y=130): return path(f"M{x - 10} {y - 50}C{x - 20} {y - 10} {x - 60} {y} {x - 70} {y + 30}C{x - 40} {y + 30} {x - 20} {y + 10} {x - 8} {y}C{x - 10} {y + 20} {x - 20} {y + 40} {x - 10} {y + 48}C{x + 4} {y + 30} {x + 6} {y + 14} {x + 6} {y}C{x + 20} {y + 16} {x + 50} {y + 30} {x + 72} {y + 26}C{x + 60} {y} {x + 24} {y - 10} {x + 10} {y - 50}Z", YELLOW)
def grapes(x=100, y=96):
    pts = [(-24, 0), (0, 0), (24, 0), (-12, 22), (12, 22), (-24, 44), (0, 44), (24, 44), (-12, 66), (12, 66), (0, 88)]
    return line(x, y - 26, x + 6, y - 44) + path(f"M{x + 6} {y - 36}C{x + 30} {y - 56} {x + 48} {y - 40} {x + 38} {y - 26}C{x + 26} {y - 18} {x + 14} {y - 26} {x + 6} {y - 36}Z", GREEN) + "".join(circ(x + dx, y + dy, 14, PURPLE) for dx, dy in pts)
def watermelon(x=100, y=130): return path(f"M{x - 70} {y - 20}A70 70 0 0 0 {x + 70} {y - 20}Z", GREEN) + path(f"M{x - 58} {y - 20}A58 58 0 0 0 {x + 58} {y - 20}Z", "#FF6B6B") + "".join(ell(x + dx, y + dy, 3, 6, INK, "") for dx, dy in ((-30, 0), (-10, 10), (12, 4), (32, -4), (0, 24)))
def orange(x=100, y=112): return circ(x, y, 52, ORANGE) + "".join(circ(x + dx, y + dy, 2.5, "#E07A1F", "") for dx, dy in ((-20, -10), (10, -22), (22, 8), (-6, 18), (-28, 16))) + path(f"M{x} {y - 52}C{x + 16} {y - 74} {x + 34} {y - 62} {x + 28} {y - 52}Z", GREEN)
def lemon(x=100, y=112): return ell(x, y, 58, 42, YELLOW, rot=-18) + path(f"M{x + 48} {y - 30}l12 -8", "none")
def pomegranate(x=100, y=116): return circ(x, y, 52, "#C9303C") + path(f"M{x - 14} {y - 50}L{x - 10} {y - 66}L{x} {y - 56}L{x + 10} {y - 66}L{x + 14} {y - 50}Z", "#C9303C") + "".join(circ(x + dx, y + dy, 5, "#FF8A9A", "") for dx, dy in ((-18, -6), (0, 6), (18, -4), (-6, 22), (14, 18)))
def fig(x=100, y=118): return path(f"M{x} {y - 52}C{x - 12} {y - 40} {x - 50} {y - 18} {x - 46} {y + 18}C{x - 42} {y + 48} {x + 42} {y + 48} {x + 46} {y + 18}C{x + 50} {y - 18} {x + 12} {y - 40} {x} {y - 52}Z", "#7B4A8C") + line(x, y - 52, x, y - 66)
def tomato(x=100, y=116, r=50): return circ(x, y, r, "#E8443A") + path(f"M{x - 22} {y - r + 4}L{x} {y - r - 6}L{x + 22} {y - r + 4}L{x + 8} {y - r + 10}L{x} {y - r + 2}L{x - 8} {y - r + 10}Z", GREEN, T)
def onion(x=100, y=118): return path(f"M{x} {y - 60}C{x - 6} {y - 40} {x - 56} {y - 26} {x - 52} {y + 14}C{x - 48} {y + 50} {x + 48} {y + 50} {x + 52} {y + 14}C{x + 56} {y - 26} {x + 6} {y - 40} {x} {y - 60}Z", "#B5568C") + path(f"M{x - 16} {y - 26}C{x - 26} {y + 6} {x - 12} {y + 40} {x} {y + 44}M{x + 16} {y - 26}C{x + 26} {y + 6} {x + 12} {y + 40} {x} {y + 44}", "none", T) + path(f"M{x - 8} {y + 44}l-6 10M{x} {y + 46}l0 10M{x + 8} {y + 44}l6 10", "none", T)
def carrot(x=100, y=100): return path(f"M{x - 26} {y - 26}L{x + 24} {y - 30}L{x - 6} {y + 70}Z", ORANGE) + path(f"M{x - 4} {y - 28}C{x - 30} {y - 60} {x - 10} {y - 70} {x} {y - 40}C{x + 8} {y - 74} {x + 30} {y - 64} {x + 6} {y - 28}Z", GREEN)
def radish(x=100, y=116): return circ(x, y, 40, "#E8467A") + path(f"M{x} {y + 40}L{x + 2} {y + 62}", "none") + path(f"M{x - 6} {y - 38}C{x - 30} {y - 74} {x - 6} {y - 80} {x} {y - 50}C{x + 6} {y - 82} {x + 30} {y - 74} {x + 6} {y - 38}Z", GREEN)
def potato(x=100, y=118): return ell(x, y, 62, 44, "#C89B5C", rot=-10) + "".join(circ(x + dx, y + dy, 3, "#8C6430", "") for dx, dy in ((-24, -8), (8, -18), (24, 10), (-8, 16)))
def cucumber(x=100, y=110): return ell(x, y, 74, 24, "#3E9A4B", rot=-30) + "".join(circ(x + dx, y + dy, 2.5, "#B9E3A6", "") for dx, dy in ((-36, 16), (-10, 0), (14, -10), (38, -24)))
def bean(x=100, y=110): return path(f"M{x - 70} {y + 10}C{x - 40} {y - 30} {x + 40} {y - 40} {x + 70} {y - 10}C{x + 50} {y + 10} {x - 40} {y + 30} {x - 70} {y + 10}Z", GREEN) + "".join(ell(x + dx, y + dy, 13, 10, "#8FD27A", T) for dx, dy in ((-34, 0), (0, -8), (34, -12)))
def bk_bean(x, y): return ell(x, y, 16, 11, "#F2E8D5") + circ(x, y, 4, INK, "")
def dates(x=100, y=120): return "".join(ell(x + dx, y + dy, 13, 22, "#7A3B1C", rot=r) for dx, dy, r in ((-30, 0, -20), (-8, -8, -5), (14, -4, 10), (34, 6, 20), (-18, 22, -10), (6, 20, 5), (26, 26, 15)))
def olives(x=100, y=120): return line(x - 60, y - 40, x + 60, y - 10, f'stroke="{BROWN}" stroke-width="6" stroke-linecap="round"') + "".join(ell(x + dx, y + dy, 9, 18, GREEN, rot=-30) for dx, dy in ((-40, -6), (10, 8))) + "".join(ell(x + dx, y + dy, 13, 17, "#4C5C2E") for dx, dy in ((-20, 18), (28, 28), (54, 6)))
def berries(x=100, y=118): return "".join(circ(x + dx, y + dy, 16, c) for dx, dy, c in ((-26, 0, "#3D4FB8"), (0, -14, "#C9303C"), (24, 4, "#3D4FB8"), (-6, 18, "#C9303C"), (18, 30, "#3D4FB8")))
def seed(x=100, y=128): return ell(x, y + 20, 58, 12, BROWN) + ell(x, y + 2, 14, 20, "#C89B5C") + A("u", path(f"M{x} {y - 18}C{x - 4} {y - 40} {x - 24} {y - 48} {x - 34} {y - 44}C{x - 30} {y - 30} {x - 16} {y - 26} {x} {y - 18}C{x + 4} {y - 44} {x + 24} {y - 52} {x + 36} {y - 46}C{x + 30} {y - 30} {x + 12} {y - 26} {x} {y - 18}", GREEN))
def bread(x=100, y=130): return path(f"M{x - 70} {y + 10}C{x - 76} {y - 40} {x - 30} {y - 54} {x} {y - 52}C{x + 30} {y - 54} {x + 76} {y - 40} {x + 70} {y + 10}Z", "#D9944A") + "".join(path(f"M{x + dx} {y - 34}l18 24", "none", T) for dx in (-40, -10, 20))
def flatbread(x=100, y=120): return ell(x, y, 66, 46, "#E8B46A") + "".join(circ(x + dx, y + dy, 5, "#C98A3E", "") for dx, dy in ((-30, -8), (4, -20), (24, 6), (-10, 16), (30, -16)))
def rice(x=100, y=104): return bowl(x, y, 124, "#4D96FF", "#FFFFFF") + "".join(ell(x + dx, y - 6 + dy, 6, 3, WHITE, T) for dx, dy in ((-30, -4), (-14, -10), (4, -12), (22, -8), (36, -2), (-4, 0), (14, 2)))
def stew(x=100, y=106): return bowl(x, y, 124, "#E8574B", "#F3A23B") + "".join(circ(x + dx, y - 4 + dy, 6, c, T) for dx, dy, c in ((-26, -2, GREEN), (2, -6, "#9C6B3E"), (24, -2, ORANGE)))
def salad(x=100, y=106): return "".join(ell(x + dx, y - 10 + dy, 22, 13, c, T, r) for dx, dy, c, r in ((-28, -4, "#5DBB63", -20), (2, -12, "#8BD17C", 10), (28, -2, "#5DBB63", 25), (-8, 4, "#E8443A", 0), (16, 6, "#C6D84E", 0))) + bowl(x, y, 128, "#F5F5F5")
def egg(x, y, s=1): return path(f"M{x} {y - 30 * s}C{x - 22 * s} {y - 30 * s} {x - 26 * s} {y + 2 * s} {x - 24 * s} {y + 10 * s}C{x - 20 * s} {y + 30 * s} {x + 20 * s} {y + 30 * s} {x + 24 * s} {y + 10 * s}C{x + 26 * s} {y + 2 * s} {x + 22 * s} {y - 30 * s} {x} {y - 30 * s}Z", "#FFF3DC")
def fried_egg(x=100, y=110): return path(f"M{x - 60} {y}C{x - 70} {y - 40} {x - 20} {y - 56} {x + 10} {y - 44}C{x + 50} {y - 50} {x + 74} {y - 10} {x + 56} {y + 20}C{x + 40} {y + 50} {x - 40} {y + 50} {x - 60} {y}Z", WHITE) + circ(x, y - 6, 22, YELLOW)
def steak(x=100, y=116): return path(f"M{x - 64} {y}C{x - 70} {y - 40} {x - 20} {y - 52} {x + 20} {y - 44}C{x + 66} {y - 36} {x + 72} {y + 10} {x + 40} {y + 32}C{x + 10} {y + 50} {x - 54} {y + 40} {x - 64} {y}Z", "#C2453D") + path(f"M{x - 40} {y - 4}C{x - 20} {y - 20} {x + 10} {y - 14} {x + 30} {y - 2}", "none", f'stroke="#F3E1D6" stroke-width="7" stroke-linecap="round"') + circ(x + 30, y + 16, 9, "#F3E1D6", T)
def drumstick(x=100, y=110): return path(f"M{x - 20} {y - 40}C{x - 60} {y - 44} {x - 66} {y + 10} {x - 30} {y + 20}C{x - 10} {y + 26} {x + 10} {y + 10} {x + 10} {y - 10}C{x + 12} {y - 30} {x} {y - 38} {x - 20} {y - 40}Z", "#D98A3E") + rect(x + 6, y + 4, 40, 12, WHITE, 6) + circ(x + 50, y + 4, 9, WHITE) + circ(x + 50, y + 18, 9, WHITE)
def cheese(x=100, y=130): return path(f"M{x - 64} {y + 20}L{x + 64} {y + 20}L{x + 64} {y - 20}L{x - 64} {y + 6}Z", YELLOW) + path(f"M{x - 64} {y + 6}L{x + 64} {y - 20}L{x + 30} {y - 46}Z", "#FFE08A") + "".join(circ(x + dx, y + dy, r, "#E8B020", "") for dx, dy, r in ((-20, 10, 6), (24, 4, 8), (44, 12, 4)))
def sugar(x=100, y=120): return "".join(rect(x + dx, y + dy, 40, 40, WHITE, 6) for dx, dy in ((-50, 0), (-6, 0), (-28, -36))) + "".join(circ(x + dx, y + dy, 2.5, GREY, "") for dx, dy in ((-36, 18), (16, 16), (-8, -18)))
def sweet(x=100, y=110): return path(f"M{x - 36} {y}L{x - 66} {y - 22}L{x - 66} {y + 22}Z", PINK) + path(f"M{x + 36} {y}L{x + 66} {y - 22}L{x + 66} {y + 22}Z", PINK) + circ(x, y, 34, "#FF6FA5") + path(f"M{x - 20} {y - 22}C{x} {y - 6} {x} {y + 6} {x + 20} {y + 22}", "none", f'stroke="#fff" stroke-width="6" stroke-linecap="round"')
def saltshaker(x=100, y=150, fill=WHITE): return path(f"M{x - 30} {y}L{x - 34} {y - 70}C{x - 34} {y - 100} {x + 34} {y - 100} {x + 34} {y - 70}L{x + 30} {y}Z", fill) + "".join(circ(x + dx, y - 96 + dy, 3, INK, "") for dx, dy in ((-8, 4), (6, 2), (0, -6)))
def jug(x=100, y=165, fill="#CFE9FF"): return path(f"M{x - 40} {y}L{x - 44} {y - 80}C{x - 44} {y - 96} {x - 30} {y - 110} {x - 24} {y - 118}L{x + 34} {y - 118}L{x + 40} {y - 80}L{x + 44} {y}Z", fill) + path(f"M{x + 40} {y - 96}C{x + 80} {y - 90} {x + 76} {y - 36} {x + 44} {y - 36}")
def bottle(x=100, y=170, fill="#9fd8ff"): return path(f"M{x - 32} {y}L{x - 32} {y - 80}C{x - 32} {y - 100} {x - 14} {y - 106} {x - 14} {y - 120}L{x + 14} {y - 120}C{x + 14} {y - 106} {x + 32} {y - 100} {x + 32} {y - 80}L{x + 32} {y}Z", fill) + rect(x - 16, y - 136, 32, 18, BLUE, 4) + rect(x - 32, y - 70, 64, 30, WHITE, 0)
def fork(x=100, y=100, s=1): return f'<g transform="translate({x},{y}) scale({s})">' + rect(-6, -10, 12, 80, GREY, 6) + path("M-22 -70L-22 -30C-22 -10 22 -10 22 -30L22 -70M-7 -70L-7 -36M7 -70L7 -36", GREY) + "</g>"
def knife(x=100, y=100, s=1): return f'<g transform="translate({x},{y}) scale({s})">' + rect(-8, 0, 16, 70, BROWN, 6) + path("M-8 0L-8 -70C10 -60 14 -30 8 0Z", GREY) + "</g>"
def spoon(x=100, y=100, s=1): return f'<g transform="translate({x},{y}) scale({s})">' + rect(-6, -10, 12, 80, GREY, 6) + ell(0, -40, 22, 32, GREY) + "</g>"
def ladle(x=100, y=96): return path(f"M{x + 40} {y - 70}L{x - 2} {y + 20}", "none", f'stroke="{INK}" stroke-width="18" stroke-linecap="round"') + path(f"M{x + 40} {y - 70}L{x - 2} {y + 20}", "none", f'stroke="{GREY}" stroke-width="9" stroke-linecap="round"') + path(f"M{x - 48} {y + 20}C{x - 48} {y + 70} {x + 34} {y + 70} {x + 34} {y + 20}Z", GREY)
def pot(x=100, y=150, fill=GREY): return rect(x - 60, y - 70, 120, 70, fill, 14) + rect(x - 70, y - 80, 140, 16, fill, 8) + rect(x - 84, y - 54, 18, 12, fill, 5) + rect(x + 66, y - 54, 18, 12, fill, 5)
def juice(x=100, y=165): return glass(x, y, 100, 60, ORANGE, .78) + line(x + 8, y - 128, x - 4, y - 70, f'stroke="{RED}" stroke-width="7" stroke-linecap="round"') + circ(x + 26, y - 100, 14, ORANGE)
def eggtray(x=100, y=130): return rect(x - 76, y, 152, 34, "#D8C3A0", 8) + "".join(egg(x + dx, y + dy, .7) for dx, dy in ((-52, -4), (-18, -4), (18, -4), (52, -4)))
def saltbox(x=100, y=160): return rect(x - 40, y - 110, 80, 110, BLUE, 8) + rect(x - 30, y - 84, 60, 40, WHITE, 6) + path(f"M{x + 12} {y - 110}L{x + 30} {y - 126}L{x + 40} {y - 110}", WHITE)
def fishrod(x=100, y=100): return line(x - 70, y + 70, x + 50, y - 60, f'stroke="{BROWN}" stroke-width="8" stroke-linecap="round"') + A("st", line(x + 50, y - 60, x + 50, y + 30, T) + ell(x + 50, y + 44, 20, 9, "#4D96FF", T) + path(f"M{x + 68} {y + 44}l12 -8l0 16z", "#4D96FF", T)) + circ(x - 42, y + 42, 10, GREY)

# ---- animals: birds and small things (the four-legged ones are in kit2) -------------------------------------------------------
def monkey(x=100, y=172): return A("st", line(x, y - 150, x, y - 120, f'stroke="{BROWN}" stroke-width="8" stroke-linecap="round"') + ell(x, y - 82, 30, 38, "#8C5A2B") + circ(x, y - 132, 22, "#8C5A2B") + circ(x - 24, y - 134, 9, "#C48F66") + circ(x + 24, y - 134, 9, "#C48F66") + ell(x, y - 126, 14, 11, "#C48F66", T) + path(f"M{x - 26} {y - 96}C{x - 46} {y - 120} {x - 30} {y - 150} {x - 6} {y - 150}M{x + 22} {y - 64}C{x + 50} {y - 50} {x + 60} {y - 20} {x + 40} {y - 10}", "none", f'stroke="{INK}" stroke-width="10" stroke-linecap="round"'), origin="50% 0%") + line(x - 60, y - 152, x + 60, y - 152, f'stroke="{BROWN}" stroke-width="10" stroke-linecap="round"')
def mouse(x=100, y=140): return A("s", path(f"M{x - 40} {y}C{x - 70} {y} {x - 80} {y - 20} {x - 64} {y - 34}", "none", O)) + path(f"M{x - 44} {y}C{x - 44} {y - 44} {x + 20} {y - 54} {x + 54} {y}Z", GREY) + circ(x + 10, y - 40, 14, "#D7DDE1") + circ(x + 56, y - 2, 4, INK, "")
def bird(x=100, y=110, c=BLUE, beak=ORANGE, crest="", tail=None, s=1.0):
    t = tail if tail is not None else path(f"M{x - 34 * s} {y}L{x - 66 * s} {y - 14 * s}L{x - 60 * s} {y + 16 * s}Z", c)
    return (t + ell(x, y, 40 * s, 30 * s, c) + circ(x + 34 * s, y - 24 * s, 20 * s, c) + path(f"M{x + 52 * s} {y - 28 * s}L{x + 72 * s} {y - 20 * s}L{x + 52 * s} {y - 14 * s}Z", beak, T) + crest +
            A("k", path(f"M{x - 14 * s} {y - 6 * s}C{x - 4 * s} {y - 44 * s} {x + 22 * s} {y - 40 * s} {x + 18 * s} {y - 6 * s}Z", c)) +
            line(x - 6 * s, y + 28 * s, x - 10 * s, y + 46 * s, T) + line(x + 10 * s, y + 28 * s, x + 12 * s, y + 46 * s, T))
def rooster(x=100, y=116): return bird(x, y, "#F6F1E7", YELLOW, path(f"M{x + 20} {y - 42}C{x + 18} {y - 60} {x + 34} {y - 62} {x + 34} {y - 48}C{x + 40} {y - 62} {x + 54} {y - 56} {x + 48} {y - 40}Z", RED), path(f"M{x - 34} {y - 6}C{x - 70} {y - 40} {x - 80} {y - 10} {x - 66} {y + 20}C{x - 56} {y + 10} {x - 44} {y + 10} {x - 34} {y + 6}Z", "#2E7263"))
def peacock(x=110, y=130): return "".join(path(f"M{x - 20} {y}L{x - 20 + 80 * c} {y - 80 * s_}", "none", f'stroke="#2E7263" stroke-width="6"') + circ(x - 20 + 82 * c, y - 82 * s_, 12, "#3D4FB8") + circ(x - 20 + 82 * c, y - 82 * s_, 5, "#5DBB63", "") for c, s_ in ((-0.94, .34), (-.77, .64), (-.5, .87), (-.17, .98), (.17, .98), (.5, .87))) + bird(x, y, "#3D4FB8", ORANGE, path(f"M{x + 34} {y - 44}l-4 -14M{x + 40} {y - 44}l2 -14", "none", T), "", .8)
def crow(x=100, y=116): return bird(x, y, "#2B2F36", "#555", "")
def eagle(x=100, y=116): return bird(x, y, "#7A4A28", YELLOW, path(f"M{x + 20} {y - 38}C{x + 30} {y - 46} {x + 46} {y - 44} {x + 52} {y - 34}", WHITE, T))
def hoopoe(x=100, y=116): return bird(x, y, "#E9A04B", "#555", path(f"M{x + 22} {y - 40}L{x + 10} {y - 70}L{x + 28} {y - 46}L{x + 30} {y - 76}L{x + 38} {y - 46}L{x + 50} {y - 66}L{x + 44} {y - 40}Z", ORANGE), path(f"M{x - 34} {y}L{x - 66} {y - 14}L{x - 60} {y + 16}Z", "#2B2F36"))
def fish(x=100, y=104, c=BLUE): return A("x", path(f"M{x - 40} {y}L{x - 70} {y - 22}L{x - 70} {y + 22}Z", c) + ell(x, y, 50, 30, c) + circ(x + 28, y - 6, 4, INK, "") + path(f"M{x - 6} {y - 28}C{x} {y - 46} {x + 20} {y - 40} {x + 20} {y - 26}", c, T))
def whale(x=100, y=120): return A("u", path(f"M{x - 70} {y}C{x - 70} {y - 50} {x + 60} {y - 56} {x + 70} {y}C{x + 70} {y + 24} {x - 50} {y + 30} {x - 70} {y}Z", "#4D7FB8") + path(f"M{x - 66} {y - 4}L{x - 92} {y - 30}L{x - 84} {y + 2}L{x - 92} {y + 26}Z", "#4D7FB8") + path(f"M{x - 40} {y + 10}C{x - 10} {y + 22} {x + 30} {y + 20} {x + 60} {y + 6}", "none", T)) + A("r", path(f"M{x + 20} {y - 60}c-6 -14 -16 -16 -22 -12M{x + 20} {y - 60}c6 -14 16 -16 22 -12M{x + 20} {y - 52}l0 -14", "none", f'stroke="#4D96FF" stroke-width="5" stroke-linecap="round"'))
def frog(x=100, y=140): return A("h", ell(x, y - 20, 50, 34, "#5DBB63") + circ(x - 26, y - 52, 14, "#5DBB63") + circ(x + 26, y - 52, 14, "#5DBB63") + path(f"M{x - 46} {y - 4}C{x - 70} {y + 6} {x - 66} {y + 20} {x - 44} {y + 16}M{x + 46} {y - 4}C{x + 70} {y + 6} {x + 66} {y + 20} {x + 44} {y + 16}", "#5DBB63"))
def snake(x=100, y=130): return A("s", path(f"M{x - 70} {y + 30}C{x - 40} {y + 50} {x - 20} {y} {x} {y + 10}C{x + 20} {y + 20} {x + 30} {y + 40} {x + 50} {y + 30}C{x + 60} {y + 24} {x + 50} {y - 20} {x + 40} {y - 30}", "none", f'stroke="{INK}" stroke-width="26" stroke-linecap="round"') + path(f"M{x - 70} {y + 30}C{x - 40} {y + 50} {x - 20} {y} {x} {y + 10}C{x + 20} {y + 20} {x + 30} {y + 40} {x + 50} {y + 30}C{x + 60} {y + 24} {x + 50} {y - 20} {x + 40} {y - 30}", "none", f'stroke="#5DBB63" stroke-width="16" stroke-linecap="round"') + ell(x + 38, y - 40, 18, 13, "#5DBB63") + path(f"M{x + 50} {y - 50}l12 -8", "none", f'stroke="{RED}" stroke-width="4" stroke-linecap="round"'))
def spider(x=100, y=110): return line(x, 10, x, y - 30, T) + A("u", "".join(path(f"M{x} {y}C{x + 30 * d} {y - 30 + k * 16} {x + 50 * d} {y - 20 + k * 16} {x + 60 * d} {y + 10 + k * 14}", "none", O) for d in (-1, 1) for k in range(4)) + circ(x, y, 24, "#2B2F36") + circ(x, y - 28, 14, "#2B2F36"))
def fly(x, y, s=1): return A("b", ell(x, y, 12 * s, 9 * s, "#2B2F36") + A("k", ell(x - 6 * s, y - 12 * s, 9 * s, 6 * s, "#E4F4FF", T, -30) + ell(x + 6 * s, y - 12 * s, 9 * s, 6 * s, "#E4F4FF", T, 30)))
def crocodile(x=100, y=130): return A("x", path(f"M{x - 80} {y}C{x - 70} {y - 24} {x + 30} {y - 30} {x + 50} {y - 20}L{x + 84} {y - 14}L{x + 84} {y}L{x + 50} {y + 4}C{x + 20} {y + 20} {x - 50} {y + 20} {x - 80} {y}Z", "#5D8B3E") + "".join(path(f"M{x + dx} {y - 22}l6 -10l6 10", "#5D8B3E", T) for dx in (-40, -20, 0, 20)) + path(f"M{x + 50} {y - 8}L{x + 84} {y - 8}", "none", T))

# ---- nature ------------------------------------------------------------------------------------------------------------------
def sun(x=100, y=100, r=34, rays=True): return (A("t", "".join(line(x + (r + 10) * c, y + (r + 10) * s, x + (r + 26) * c, y + (r + 26) * s, f'stroke="{ORANGE}" stroke-width="8" stroke-linecap="round"') for c, s in ((1, 0), (.7, .7), (0, 1), (-.7, .7), (-1, 0), (-.7, -.7), (0, -1), (.7, -.7)))) if rays else "") + circ(x, y, r, YELLOW)
def moon(x=100, y=96, r=46, fill="#FFE08A"):   # a crescent opening to the right
    import math
    a = math.radians(38); px, dy = x + r * math.sin(a), r * math.cos(a)
    return path(f"M{px:.1f} {y - dy:.1f}A{r} {r} 0 1 0 {px:.1f} {y + dy:.1f}A{r * .86:.1f} {r * .86:.1f} 0 0 1 {px:.1f} {y - dy:.1f}Z", fill)
def cloud(x=100, y=100, s=1.0, fill=WHITE): return path(f"M{x - 60 * s} {y + 20 * s}C{x - 86 * s} {y + 20 * s} {x - 86 * s} {y - 16 * s} {x - 58 * s} {y - 16 * s}C{x - 56 * s} {y - 46 * s} {x - 14 * s} {y - 50 * s} {x - 4 * s} {y - 26 * s}C{x + 10 * s} {y - 54 * s} {x + 58 * s} {y - 46 * s} {x + 56 * s} {y - 14 * s}C{x + 84 * s} {y - 14 * s} {x + 84 * s} {y + 20 * s} {x + 58 * s} {y + 20 * s}Z", fill)
def rain(x=100, y=128, n=4): return "".join(A("f", path(f"M{x - 36 + i * 24} {y}l-4 14", "none", f'stroke="#4D96FF" stroke-width="7" stroke-linecap="round"'), d=i % 4) for i in range(n))
def snowflake(x=100, y=100, r=40, cls="t"): return A(cls, "".join(line(x - r * c, y - r * s, x + r * c, y + r * s, f'stroke="#4D96FF" stroke-width="8" stroke-linecap="round"') for c, s in ((1, 0), (.5, .87), (-.5, .87))) + circ(x, y, 8, "#4D96FF", ""))
def tree(x=100, y=172, s=1.0, fill=GREEN, fruit=None):
    f = "".join(circ(x + dx * s, y + dy * s, 7 * s, fruit, T) for dx, dy in ((-24, -104), (18, -118), (30, -88), (-6, -80))) if fruit else ""
    return rect(x - 12 * s, y - 70 * s, 24 * s, 70 * s, BROWN, 6) + A("s", circ(x, y - 104 * s, 52 * s, fill) + circ(x - 34 * s, y - 84 * s, 30 * s, fill) + circ(x + 34 * s, y - 84 * s, 30 * s, fill) + f)
def palm(x=100, y=176): return path(f"M{x - 10} {y}C{x - 6} {y - 50} {x - 2} {y - 90} {x + 6} {y - 120}L{x + 22} {y - 118}C{x + 12} {y - 90} {x + 10} {y - 50} {x + 14} {y}Z", BROWN) + A("s", "".join(path(f"M{x + 14} {y - 122}C{x + 14 + 30 * c} {y - 150 + 10 * k} {x + 14 + 60 * c} {y - 132 + 18 * k} {x + 14 + 72 * c} {y - 96 + 20 * k}C{x + 14 + 50 * c} {y - 118 + 16 * k} {x + 14 + 26 * c} {y - 124} {x + 14} {y - 122}Z", GREEN) for c, k in ((1, 0), (-1, 0), (.8, 1.2), (-.8, 1.2))) + "".join(circ(x + 14 + dx, y - 112 + dy, 7, "#7A3B1C", T) for dx, dy in ((-8, 4), (6, 6), (0, 12))))
def flower(x=100, y=174, c=PINK): return line(x, y, x, y - 80, f'stroke="{INK}" stroke-width="12" stroke-linecap="round"') + line(x, y, x, y - 80, f'stroke="{GREEN}" stroke-width="6" stroke-linecap="round"') + ell(x - 22, y - 40, 18, 9, GREEN, T, -30) + A("s", "".join(circ(x + 24 * cc, y - 104 + 24 * ss, 17, c) for cc, ss in ((1, 0), (.31, .95), (-.81, .59), (-.81, -.59), (.31, -.95))) + circ(x, y - 104, 15, YELLOW))
def grass(x=100, y=170): return A("s", "".join(path(f"M{x + dx - 10} {y}C{x + dx - 8} {y - 30} {x + dx - 2} {y - 50} {x + dx + 4} {y - 70 - (dx % 3) * 6}C{x + dx + 4} {y - 40} {x + dx + 6} {y - 20} {x + dx + 10} {y}Z", g) for dx, g in ((-60, "#5DBB63"), (-36, "#3E9A4B"), (-12, "#5DBB63"), (12, "#3E9A4B"), (36, "#5DBB63"), (60, "#3E9A4B")))) + rect(x - 78, y - 4, 156, 12, BROWN, 6)
def mountains(x=100, y=168): return path(f"M{x - 86} {y}L{x - 30} {y - 96}L{x + 10} {y - 30}L{x + 40} {y - 76}L{x + 86} {y}Z", "#8E9BA6") + path(f"M{x - 46} {y - 68}L{x - 30} {y - 96}L{x - 14} {y - 68}L{x - 24} {y - 74}L{x - 30} {y - 64}Z", WHITE, T) + path(f"M{x + 30} {y - 60}L{x + 40} {y - 76}L{x + 52} {y - 58}Z", WHITE, T)
def sea(x=100, y=120): return A("x", "".join(path(f"M{x - 90} {y + k * 26}q15 -14 30 0t30 0t30 0t30 0t30 0t30 0", "none", f'stroke="#4D96FF" stroke-width="9" stroke-linecap="round"') for k in range(3)))
def river(x=100, y=100): return path(f"M{x - 40} {y - 90}C{x + 30} {y - 50} {x - 60} {y - 10} {x - 10} {y + 30}C{x + 30} {y + 60} {x} {y + 80} {x + 20} {y + 94}", "none", f'stroke="#4D96FF" stroke-width="30" stroke-linecap="round"') + A("x", path(f"M{x - 30} {y - 40}l14 0M{x - 24} {y + 20}l14 0M{x + 6} {y + 60}l14 0", "none", f'stroke="#fff" stroke-width="5" stroke-linecap="round"'))
def dunes(x=100, y=160): return path(f"M{x - 94} {y}C{x - 60} {y - 50} {x - 20} {y - 50} {x + 10} {y - 10}C{x + 40} {y - 60} {x + 80} {y - 50} {x + 94} {y - 20}L{x + 94} {y + 30}L{x - 94} {y + 30}Z", "#F2C46B")
def rock(x=100, y=150): return path(f"M{x - 70} {y + 10}L{x - 56} {y - 40}L{x - 10} {y - 66}L{x + 44} {y - 50}L{x + 72} {y}L{x + 56} {y + 16}Z", "#9AA4AC") + path(f"M{x - 10} {y - 66}L{x} {y - 10}L{x + 72} {y}", "none", T)
def cave(x=100, y=160): return mountains(x, y) + path(f"M{x - 30} {y}C{x - 30} {y - 50} {x + 20} {y - 50} {x + 20} {y}Z", "#3A3A3A")
def grains(x=100, y=176): return A("s", "".join(line(x + dx, y, x + dx + 4, y - 100, f'stroke="{GOLD}" stroke-width="5"') + "".join(ell(x + dx + 4 + (5 if k % 2 else -5), y - 100 + k * 12, 7, 12, GOLD, T, 30 if k % 2 else -30) for k in range(5)) for dx in (-30, 0, 30)))
def leaf(x=100, y=100, c=ORANGE): return path(f"M{x - 40} {y + 40}C{x - 50} {y - 20} {x + 10} {y - 50} {x + 46} {y - 46}C{x + 50} {y + 10} {x} {y + 50} {x - 40} {y + 40}Z", c) + path(f"M{x - 40} {y + 40}L{x + 30} {y - 30}", "none", T)
def blossom(x=100, y=110): return line(x - 70, y + 50, x + 50, y - 40, f'stroke="{BROWN}" stroke-width="9" stroke-linecap="round"') + "".join(A("p", "".join(circ(cx + 12 * c, cy + 12 * s, 9, "#FFC1D9", T) for c, s in ((1, 0), (.31, .95), (-.81, .59), (-.81, -.59), (.31, -.95))) + circ(cx, cy, 6, YELLOW, T), d=i) for i, (cx, cy) in enumerate(((x - 30, y + 14), (x + 10, y - 20), (x + 40, y - 52))))
def thermo(x=100, y=100, level=.5, c=RED): return rect(x - 16, y - 70, 32, 110, WHITE, 16) + circ(x, y + 50, 26, c) + rect(x - 7, y + 40 - 100 * level, 14, 100 * level + 10, c, 7, "") + "".join(line(x + 16, y - 50 + k * 22, x + 28, y - 50 + k * 22, T) for k in range(4))
def snowman(x=100, y=172): return circ(x, y - 40, 40, WHITE) + circ(x, y - 108, 30, WHITE) + path(f"M{x - 2} {y - 108}l26 6l-26 6z", ORANGE, T) + rect(x - 26, y - 150, 52, 10, RED, 5) + rect(x - 18, y - 172, 36, 24, RED, 4)
def umbrella(x=100, y=100): return A("st", path(f"M{x - 70} {y - 10}C{x - 66} {y - 70} {x + 66} {y - 70} {x + 70} {y - 10}C{x + 50} {y - 24} {x + 30} {y - 24} {x + 10} {y - 10}C{x - 10} {y - 24} {x - 30} {y - 24} {x - 50} {y - 10}C{x - 56} {y - 16} {x - 64} {y - 18} {x - 70} {y - 10}Z", RED) + path(f"M{x} {y - 14}L{x} {y + 60}C{x} {y + 76} {x - 22} {y + 76} {x - 22} {y + 62}", "none", O), origin="50% 0%")
def wind(x=100, y=100): return "".join(A("x", path(f"M{x - 70} {y - 30 + k * 30}L{x + 30 - k * 10} {y - 30 + k * 30}C{x + 60} {y - 30 + k * 30} {x + 60} {y - 64 + k * 30} {x + 36} {y - 60 + k * 30}", "none", f'stroke="#9AA4AC" stroke-width="9" stroke-linecap="round"'), d=k) for k in range(3))
def drops(x=100, y=100): return "".join(A("f", path(f"M{x + dx} {y + dy - 18}C{x + dx + 14} {y + dy} {x + dx + 12} {y + dy + 14} {x + dx} {y + dy + 14}C{x + dx - 12} {y + dy + 14} {x + dx - 14} {y + dy} {x + dx} {y + dy - 18}Z", "#4D96FF", T), d=i) for i, (dx, dy) in enumerate(((-30, -20), (10, -36), (30, 10), (-12, 24))))
def earth(x=100, y=100, r=60): return circ(x, y, r, "#4D96FF") + path(f"M{x - 30} {y - 40}C{x - 10} {y - 50} {x + 10} {y - 30} {x} {y - 10}C{x - 20} {y} {x - 30} {y + 20} {x - 46} {y + 10}C{x - 52} {y - 10} {x - 46} {y - 30} {x - 30} {y - 40}Z", GREEN, T) + path(f"M{x + 20} {y + 10}C{x + 40} {y + 4} {x + 52} {y + 20} {x + 40} {y + 40}C{x + 24} {y + 46} {x + 14} {y + 30} {x + 20} {y + 10}Z", GREEN, T)
def sprout(x=100, y=160): return ell(x, y, 64, 12, BROWN) + A("u", line(x, y, x, y - 60, f'stroke="{GREEN}" stroke-width="7" stroke-linecap="round"') + path(f"M{x} {y - 50}C{x - 10} {y - 80} {x - 44} {y - 84} {x - 50} {y - 74}C{x - 40} {y - 54} {x - 14} {y - 50} {x} {y - 50}Z", GREEN) + path(f"M{x} {y - 40}C{x + 10} {y - 70} {x + 44} {y - 74} {x + 50} {y - 64}C{x + 40} {y - 44} {x + 14} {y - 40} {x} {y - 40}Z", "#8BD17C"))
def roots(x=100, y=96): return rect(x - 70, y - 6, 140, 12, BROWN, 6) + path(f"M{x} {y - 50}C{x - 6} {y - 70} {x - 30} {y - 76} {x - 40} {y - 70}C{x - 30} {y - 52} {x - 10} {y - 50} {x} {y - 50}Z", GREEN) + line(x, y - 50, x, y, T) + A("u", path(f"M{x} {y + 6}C{x - 4} {y + 40} {x - 30} {y + 50} {x - 40} {y + 80}M{x} {y + 6}C{x + 6} {y + 40} {x + 30} {y + 56} {x + 36} {y + 82}M{x} {y + 20}L{x + 2} {y + 84}", "none", f'stroke="#C89B5C" stroke-width="7" stroke-linecap="round"'))
def mud(x=100, y=140): return ell(x, y, 80, 24, "#7A5232") + ell(x - 20, y - 6, 20, 6, "#946B47", "") + A("g", circ(x + 30, y - 4, 6, "#946B47", T))
def smoke(x=100, y=100): return rect(x - 60, y + 10, 120, 60, GREY, 6) + rect(x - 40, y - 50, 22, 62, "#8E9BA6", 4) + rect(x + 10, y - 30, 22, 42, "#8E9BA6", 4) + "".join(A("r", circ(x - 28 + dx, y - 70 + dy, 14, "#6B7378", T), d=i) for i, (dx, dy) in enumerate(((0, 0), (12, -18), (50, 10))))

