    return f'<g transform="translate({x},{y}) scale({s})">' + path("M-34 60L-38 0C-40 -10 -26 -12 -24 0L-24 -50C-24 -62 -8 -62 -8 -50L-8 -62C-8 -74 8 -74 8 -62L8 -54C8 -66 24 -66 24 -54L24 -40C24 -50 38 -50 38 -40L38 20C38 44 26 60 14 60Z", fill) + "</g>"
