def heart(x=100, y=104, r=1.0, fill=RED): return path(f"M{x} {y + 46 * r}C{x - 70 * r} {y} {x - 54 * r} {y - 60 * r} {x} {y - 30 * r}C{x + 54 * r} {y - 60 * r} {x + 70 * r} {y} {x} {y + 46 * r}Z", fill)
def tooth(x=100, y=104, fill=WHITE): return path(f"M{x - 40} {y - 40}C{x - 50} {y - 10} {x - 36} {y + 20} {x - 30} {y + 50}C{x - 26} {y + 62} {x - 14} {y + 60} {x - 12} {y + 44}C{x - 10} {y + 26} {x + 10} {y + 26} {x + 12} {y + 44}C{x + 14} {y + 60} {x + 26} {y + 62} {x + 30} {y + 50}C{x + 36} {y + 20} {x + 50} {y - 10} {x + 40} {y - 40}C{x + 26} {y - 56} {x + 10} {y - 44} {x} {y - 44}C{x - 10} {y - 44} {x - 26} {y - 56} {x - 40} {y - 40}Z", fill)
def tongue(x=100, y=96): return path(f"M{x - 60} {y - 20}C{x - 30} {y - 4} {x + 30} {y - 4} {x + 60} {y - 20}C{x + 50} {y + 10} {x - 50} {y + 10} {x - 60} {y - 20}Z", "#C9303C") + A("k", path(f"M{x - 30} {y}C{x - 34} {y + 60} {x + 34} {y + 60} {x + 30} {y}Z", "#FF7A8A") + line(x, y + 6, x, y + 34, T), origin="50% 0%")
def head(x=100, y=110, skin=SKIN[1]): return path(f"M{x - 30} {y + 70}L{x - 26} {y + 34}L{x + 26} {y + 34}L{x + 30} {y + 70}Z", BLUE) + circ(x, y - 10, 46, skin)
def arm(x=100, y=100): return path(f"M{x - 70} {y + 40}C{x - 40} {y + 40} {x - 10} {y + 36} {x + 10} {y + 10}C{x + 20} {y - 4} {x + 30} {y - 30} {x + 40} {y - 50}", "none", f'stroke="{INK}" stroke-width="34" stroke-linecap="round"') + path(f"M{x - 70} {y + 40}C{x - 40} {y + 40} {x - 10} {y + 36} {x + 10} {y + 10}C{x + 20} {y - 4} {x + 30} {y - 30} {x + 40} {y - 50}", "none", f'stroke="{SKIN[1]}" stroke-width="24" stroke-linecap="round"') + circ(x + 44, y - 56, 18, SKIN[1])
def kidney(x=100, y=100): return path(f"M{x - 10} {y - 56}C{x - 60} {y - 60} {x - 66} {y + 50} {x - 6} {y + 56}C{x + 30} {y + 58} {x + 40} {y + 24} {x + 12} {y + 8}C{x} {y} {x + 2} {y - 20} {x + 14} {y - 26}C{x + 40} {y - 40} {x + 30} {y - 54} {x - 10} {y - 56}Z", "#B5465A")
def bone(x=100, y=100): return path(f"M{x - 50} {y + 26}L{x + 40} {y - 34}", "none", f'stroke="{INK}" stroke-width="30" stroke-linecap="round"') + path(f"M{x - 50} {y + 26}L{x + 40} {y - 34}", "none", f'stroke="#F7F3EA" stroke-width="20" stroke-linecap="round"') + "".join(circ(x + dx, y + dy, 15, "#F7F3EA") for dx, dy in ((-66, 18), (-56, 44), (56, -42), (46, -64)))
def chest(x=100, y=104): return path(f"M{x - 64} {y + 60}L{x - 60} {y - 40}Q{x} {y - 66} {x + 60} {y - 40}L{x + 64} {y + 60}Z", BLUE) + A("p", heart(x - 18, y - 6, .4))
def lips(x=100, y=104): return path(f"M{x - 60} {y}C{x - 30} {y - 30} {x - 10} {y - 20} {x} {y - 12}C{x + 10} {y - 20} {x + 30} {y - 30} {x + 60} {y}C{x + 30} {y + 30} {x - 30} {y + 30} {x - 60} {y}Z", "#E06C7A")

# ---- things ------------------------------------------------------------------------------------------------------------------
def book(x=100, y=110, c=TEAL, w=1.0): return path(f"M{x} {y - 44 * w}C{x - 30 * w} {y - 60 * w} {x - 66 * w} {y - 56 * w} {x - 80 * w} {y - 44 * w}L{x - 80 * w} {y + 44 * w}C{x - 60 * w} {y + 34 * w} {x - 24 * w} {y + 34 * w} {x} {y + 50 * w}Z", WHITE) + path(f"M{x} {y - 44 * w}C{x + 30 * w} {y - 60 * w} {x + 66 * w} {y - 56 * w} {x + 80 * w} {y - 44 * w}L{x + 80 * w} {y + 44 * w}C{x + 60 * w} {y + 34 * w} {x + 24 * w} {y + 34 * w} {x} {y + 50 * w}Z", WHITE) + "".join(path(f"M{x + d * 16 * w} {y + (k * 14 - 24) * w}L{x + d * 62 * w} {y + (k * 14 - 28) * w}", "none", f'stroke="{c}" stroke-width="5" stroke-linecap="round"') for d in (-1, 1) for k in range(4))
def closedbook(x=100, y=110, c=TEAL, label=""): return rect(x - 50, y - 64, 100, 128, c, 10) + rect(x - 50, y + 48, 100, 16, WHITE, 4) + (label if label else rect(x - 30, y - 40, 60, 22, WHITE, 6))
def books(x=100, y=164): return "".join(rect(x + dx, y - h, 30, h, c, 4) for dx, h, c in ((-70, 100, RED), (-38, 120, TEAL), (-6, 90, YELLOW), (26, 110, PURPLE))) + path(f"M{x + 56} {y}L{x + 66} {y - 100}L{x + 90} {y - 96}L{x + 86} {y}Z", BLUE) + rect(x - 84, y, 178, 10, BROWN, 4)
def notebook(x=100, y=104): return rect(x - 50, y - 66, 100, 132, YELLOW, 8) + "".join(circ(x - 50, y - 50 + k * 22, 7, WHITE) for k in range(6)) + "".join(line(x - 30, y - 40 + k * 20, x + 34, y - 40 + k * 20, T) for k in range(5))
def pen(x=100, y=100, c=BLUE): return A("c", path(f"M{x - 54} {y + 54}L{x - 64} {y + 64}L{x - 40} {y + 64}Z", INK) + path(f"M{x - 50} {y + 50}L{x + 50} {y - 50}L{x + 64} {y - 36}L{x - 36} {y + 64}Z", c) + path(f"M{x + 40} {y - 40}L{x + 54} {y - 26}", "none", T))
def pencil(x=100, y=100): return path(f"M{x - 50} {y + 50}L{x + 50} {y - 50}L{x + 64} {y - 36}L{x - 36} {y + 64}Z", YELLOW) + path(f"M{x - 50} {y + 50}L{x - 62} {y + 62}L{x - 36} {y + 64}Z", "#F2D3A6") + path(f"M{x + 50} {y - 50}L{x + 58} {y - 58}C{x + 64} {y - 62} {x + 74} {y - 52} {x + 70} {y - 46}L{x + 64} {y - 36}Z", PINK)
def paper(x=100, y=100, w=110, h=140, lines=5, fill=WHITE): return rect(x - w / 2, y - h / 2, w, h, fill, 8) + "".join(line(x - w / 2 + 18, y - h / 2 + 30 + k * 20, x + w / 2 - 18, y - h / 2 + 30 + k * 20, f'stroke="{GREY}" stroke-width="5" stroke-linecap="round"') for k in range(lines))
def check(x, y, s=1.0, c=GREEN): return path(f"M{x - 24 * s} {y}L{x - 6 * s} {y + 18 * s}L{x + 26 * s} {y - 18 * s}", "none", f'stroke="{c}" stroke-width="{12 * s}" stroke-linecap="round" stroke-linejoin="round"')
def cross(x, y, s=1.0, c=RED): return path(f"M{x - 20 * s} {y - 20 * s}L{x + 20 * s} {y + 20 * s}M{x + 20 * s} {y - 20 * s}L{x - 20 * s} {y + 20 * s}", "none", f'stroke="{c}" stroke-width="{12 * s}" stroke-linecap="round"')
def bulb(x=100, y=92): return A("g", circ(x, y, 66, "#FFF3B0", ""), ) + path(f"M{x - 22} {y + 40}C{x - 22} {y + 20} {x - 46} {y + 6} {x - 46} {y - 20}C{x - 46} {y - 48} {x - 24} {y - 64} {x} {y - 64}C{x + 24} {y - 64} {x + 46} {y - 48} {x + 46} {y - 20}C{x + 46} {y + 6} {x + 22} {y + 20} {x + 22} {y + 40}Z", YELLOW) + rect(x - 22, y + 40, 44, 28, GREY, 6) + line(x - 22, y + 54, x + 22, y + 54, T)
def phone(x=100, y=100): return rect(x - 36, y - 70, 72, 140, "#2B2F36", 14) + rect(x - 28, y - 56, 56, 102, "#9FD8FF", 6, "") + circ(x, y + 58, 5, GREY, "")
def handset(x=100, y=100): return A("j", path(f"M{x - 60} {y - 40}C{x - 50} {y - 70} {x - 20} {y - 66} {x - 10} {y - 50}L{x - 24} {y - 30}C{x - 14} {y} {x + 10} {y + 24} {x + 34} {y + 30}L{x + 52} {y + 14}C{x + 70} {y + 22} {x + 72} {y + 52} {x + 44} {y + 62}C{x - 20} {y + 64} {x - 76} {y + 10} {x - 60} {y - 40}Z", "#2B2F36"))
def laptop(x=100, y=120): return rect(x - 60, y - 70, 120, 80, "#2B2F36", 8) + rect(x - 50, y - 60, 100, 60, "#9FD8FF", 4, "") + path(f"M{x - 76} {y + 10}L{x + 76} {y + 10}L{x + 66} {y + 26}L{x - 66} {y + 26}Z", GREY)
def tv(x=100, y=104): return rect(x - 70, y - 56, 140, 96, "#2B2F36", 10) + rect(x - 60, y - 46, 120, 76, "#9FD8FF", 4, "") + A("g", path(f"M{x - 10} {y - 22}L{x + 16} {y - 8}L{x - 10} {y + 6}Z", WHITE, T)) + line(x - 30, y + 40, x - 40, y + 60) + line(x + 30, y + 40, x + 40, y + 60)
def radio(x=100, y=116): return rect(x - 70, y - 40, 140, 80, ORANGE, 12) + circ(x - 30, y, 24, WHITE) + circ(x - 30, y, 10, GREY, T) + rect(x + 10, y - 20, 44, 12, WHITE, 4) + circ(x + 32, y + 20, 8, WHITE, T) + line(x + 40, y - 40, x + 64, y - 80) + waves(x + 66, y - 30, 2, .8)
def newspaper(x=100, y=104): return rect(x - 66, y - 60, 132, 120, WHITE, 6) + rect(x - 52, y - 48, 104, 22, INK, 4, "") + rect(x - 52, y - 16, 46, 48, GREY, 4, "") + "".join(line(x + 4, y - 14 + k * 14, x + 52, y - 14 + k * 14, T) for k in range(4)) + "".join(line(x - 52, y + 44 + k * 10, x + 52, y + 44 + k * 10, T) for k in range(1))
def envelope(x=100, y=104, fill=WHITE): return rect(x - 66, y - 44, 132, 88, fill, 8) + path(f"M{x - 66} {y - 40}L{x} {y + 6}L{x + 66} {y - 40}", "none")
def stamp(x=100, y=104, c=RED): return rect(x - 44, y - 54, 88, 108, WHITE, 2) + rect(x - 32, y - 42, 64, 84, c, 4) + star(x, y, 20, YELLOW, T)
def passport(x=100, y=104, c="#2E4A8C"): return rect(x - 48, y - 66, 96, 132, c, 10) + circ(x, y - 10, 24, "none", f'stroke="{GOLD}" stroke-width="5"') + path(f"M{x - 24} {y - 10}L{x + 24} {y - 10}M{x} {y - 34}C{x - 14} {y - 20} {x - 14} {y} {x} {y + 14}C{x + 14} {y} {x + 14} {y - 20} {x} {y - 34}", "none", f'stroke="{GOLD}" stroke-width="4"') + rect(x - 26, y + 30, 52, 8, GOLD, 4, "")
def ticket(x=100, y=104, c=PINK): return path(f"M{x - 76} {y - 36}L{x + 76} {y - 36}L{x + 76} {y - 14}C{x + 62} {y - 14} {x + 62} {y + 14} {x + 76} {y + 14}L{x + 76} {y + 36}L{x - 76} {y + 36}L{x - 76} {y + 14}C{x - 62} {y + 14} {x - 62} {y - 14} {x - 76} {y - 14}Z", c) + line(x + 30, y - 30, x + 30, y + 30, f'stroke="{INK}" stroke-width="4" stroke-dasharray="6 6"') + star(x - 16, y, 16, YELLOW, T)
def suitcase(x=100, y=120, c=ORANGE): return rect(x - 60, y - 50, 120, 90, c, 12) + path(f"M{x - 24} {y - 50}L{x - 24} {y - 72}L{x + 24} {y - 72}L{x + 24} {y - 50}", "none") + line(x - 30, y - 50, x - 30, y + 40, T) + line(x + 30, y - 50, x + 30, y + 40, T) + circ(x - 40, y + 46, 7, INK, "") + circ(x + 40, y + 46, 7, INK, "")
def briefcase(x=100, y=122): return rect(x - 64, y - 46, 128, 86, BROWN, 10) + path(f"M{x - 22} {y - 46}L{x - 22} {y - 64}L{x + 22} {y - 64}L{x + 22} {y - 46}", "none") + line(x - 64, y - 10, x + 64, y - 10, T) + rect(x - 10, y - 18, 20, 16, GOLD, 3, T)
def key(x=100, y=100): return A("s", circ(x - 30, y - 30, 28, GOLD) + circ(x - 30, y - 30, 10, WHITE, T) + path(f"M{x - 10} {y - 10}L{x + 50} {y + 50}M{x + 26} {y + 26}L{x + 40} {y + 12}M{x + 40} {y + 40}L{x + 54} {y + 26}", "none", f'stroke="{INK}" stroke-width="12" stroke-linecap="round"'), origin="20% 20%")
def lock(x=100, y=116): return path(f"M{x - 32} {y - 30}L{x - 32} {y - 52}C{x - 32} {y - 92} {x + 32} {y - 92} {x + 32} {y - 52}L{x + 32} {y - 30}", "none", f'stroke="{INK}" stroke-width="16"') + path(f"M{x - 32} {y - 30}L{x - 32} {y - 52}C{x - 32} {y - 92} {x + 32} {y - 92} {x + 32} {y - 52}L{x + 32} {y - 30}", "none", f'stroke="{GREY}" stroke-width="8"') + rect(x - 52, y - 34, 104, 80, GOLD, 12) + circ(x, y, 10, INK, "") + rect(x - 4, y, 8, 22, INK, 3, "")
def box(x=100, y=120, c="#D8A86A"): return path(f"M{x - 60} {y - 30}L{x} {y - 56}L{x + 60} {y - 30}L{x} {y - 4}Z", "#E8C08A") + path(f"M{x - 60} {y - 30}L{x - 60} {y + 40}L{x} {y + 66}L{x} {y - 4}Z", c) + path(f"M{x + 60} {y - 30}L{x + 60} {y + 40}L{x} {y + 66}L{x} {y - 4}Z", "#C08A50")
def gift(x=100, y=124): return rect(x - 56, y - 40, 112, 80, RED, 6) + rect(x - 64, y - 60, 128, 26, "#FF7A6E", 6) + rect(x - 10, y - 60, 20, 100, YELLOW, 0) + A("p", path(f"M{x} {y - 60}C{x - 30} {y - 96} {x - 50} {y - 66} {x} {y - 60}C{x + 50} {y - 66} {x + 30} {y - 96} {x} {y - 60}Z", YELLOW))
def toy(x=100, y=150): return A("h", circ(x, y - 40, 40, RED) + path(f"M{x - 40} {y - 40}C{x - 20} {y - 56} {x + 20} {y - 56} {x + 40} {y - 40}M{x - 40} {y - 40}C{x - 20} {y - 24} {x + 20} {y - 24} {x + 40} {y - 40}", "none", f'stroke="{WHITE}" stroke-width="7"') + path(f"M{x} {y - 80}C{x - 14} {y - 60} {x - 14} {y - 20} {x} {y}M{x} {y - 80}C{x + 14} {y - 60} {x + 14} {y - 20} {x} {y}", "none", f'stroke="{YELLOW}" stroke-width="7"')) + ell(x, y + 14, 34, 7, "#00000022", "")
def ball(x=100, y=120, r=40):
    k = r / 40; p = [(0, -14), (14, -4), (9, 13), (-9, 13), (-14, -4)]; e = [(0, -1), (.95, -.3), (.6, .8), (-.6, .8), (-.95, -.3)]
    return (circ(x, y, r, WHITE) + path("M" + "L".join(f"{x + a * k:.1f} {y + b * k:.1f}" for a, b in p) + "Z", INK, T) +
            "".join(line(x + a * k, y + b * k, x + c * r, y + d * r, T) for (a, b), (c, d) in zip(p, e)))
def needle(x=100, y=100): return path(f"M{x - 60} {y + 60}L{x + 50} {y - 50}", "none", f'stroke="{INK}" stroke-width="13" stroke-linecap="round"') + path(f"M{x - 60} {y + 60}L{x + 50} {y - 50}", "none", f'stroke="{GREY}" stroke-width="6" stroke-linecap="round"') + ell(x + 40, y - 40, 4, 9, WHITE, T, 45) + A("s", path(f"M{x + 40} {y - 40}C{x + 70} {y - 10} {x + 30} {y + 20} {x + 60} {y + 60}", "none", f'stroke="{RED}" stroke-width="5" stroke-linecap="round"'))
def rope(x=100, y=100): return path(f"M{x - 70} {y + 50}C{x - 30} {y + 70} {x + 20} {y + 30} {x} {y}C{x - 30} {y - 40} {x + 40} {y - 70} {x + 60} {y - 30}C{x + 70} {y - 10} {x + 50} {y + 20} {x + 70} {y + 40}", "none", f'stroke="{INK}" stroke-width="22" stroke-linecap="round"') + path(f"M{x - 70} {y + 50}C{x - 30} {y + 70} {x + 20} {y + 30} {x} {y}C{x - 30} {y - 40} {x + 40} {y - 70} {x + 60} {y - 30}C{x + 70} {y - 10} {x + 50} {y + 20} {x + 70} {y + 40}", "none", f'stroke="#D9B26A" stroke-width="13" stroke-linecap="round"')
def scales(x=100, y=150): return rect(x - 50, y, 100, 14, BROWN, 4) + line(x, y, x, y - 110) + A("j", line(x - 64, y - 104, x + 64, y - 104) + path(f"M{x - 64} {y - 104}L{x - 84} {y - 50}L{x - 44} {y - 50}Z", "none", T) + path(f"M{x + 64} {y - 104}L{x + 44} {y - 50}L{x + 84} {y - 50}Z", "none", T) + path(f"M{x - 92} {y - 50}C{x - 92} {y - 30} {x - 36} {y - 30} {x - 36} {y - 50}Z", GOLD) + path(f"M{x + 36} {y - 50}C{x + 36} {y - 30} {x + 92} {y - 30} {x + 92} {y - 50}Z", GOLD), origin="50% 0%")
def weighscale(x=100, y=150, level=0): return rect(x - 64, y - 40, 128, 40, WHITE, 12) + rect(x - 30, y - 34, 60, 22, "#9FD8FF", 4) + A("j", line(x, y - 23, x + 10 + level, y - 30, f'stroke="{RED}" stroke-width="4" stroke-linecap="round"'))
def binoculars(x=100, y=110): return circ(x - 32, y + 10, 28, "#2B2F36") + circ(x + 32, y + 10, 28, "#2B2F36") + circ(x - 32, y + 10, 16, "#9FD8FF", T) + circ(x + 32, y + 10, 16, "#9FD8FF", T) + rect(x - 14, y - 30, 28, 30, "#2B2F36", 6) + rect(x - 52, y - 36, 34, 36, "#2B2F36", 8) + rect(x + 18, y - 36, 34, 36, "#2B2F36", 8)
def glasses(x=100, y=104): return circ(x - 34, y, 26, "#CDEBFF") + circ(x + 34, y, 26, "#CDEBFF") + path(f"M{x - 8} {y - 4}C{x - 4} {y - 12} {x + 4} {y - 12} {x + 8} {y - 4}M{x - 60} {y - 6}L{x - 80} {y - 16}M{x + 60} {y - 6}L{x + 80} {y - 16}", "none")
def necklace(x=100, y=90): return path(f"M{x - 54} {y - 40}C{x - 54} {y + 30} {x + 54} {y + 30} {x + 54} {y - 40}", "none", f'stroke="{GOLD}" stroke-width="6"') + "".join(circ(x + 50 * __import__('math').sin(t), y - 40 + 60 * (1 - __import__('math').cos(t)) / 1.6, 7, WHITE, T) for t in (-1.2, -.7, -.25, .25, .7, 1.2)) + A("p", path(f"M{x} {y + 30}L{x - 14} {y + 50}L{x} {y + 74}L{x + 14} {y + 50}Z", "#4D96FF"))
def button_(x=100, y=104): return circ(x, y, 50, RED) + circ(x, y, 38, "#FF7A6E", T) + "".join(circ(x + dx, y + dy, 7, WHITE, T) for dx, dy in ((-12, -12), (12, -12), (-12, 12), (12, 12)))
def clockface(x=100, y=104, r=62, h=3, m=0, fill=WHITE, anim=True):
    import math
    ha, ma = math.radians(h % 12 * 30 + m / 2), math.radians(m * 6)
    hands = line(x, y, x + r * .5 * math.sin(ha), y - r * .5 * math.cos(ha), f'stroke="{INK}" stroke-width="8" stroke-linecap="round"')
    mh = line(x, y, x + r * .78 * math.sin(ma), y - r * .78 * math.cos(ma), f'stroke="{INK}" stroke-width="5" stroke-linecap="round"')
    return circ(x, y, r, fill) + "".join(circ(x + r * .82 * math.sin(math.radians(a)), y - r * .82 * math.cos(math.radians(a)), 3, INK, "") for a in range(0, 360, 30)) + hands + (A("t", f'<circle cx="{x}" cy="{y}" r="{r * .8:.0f}" fill="none"/>' + mh) if anim else mh) + circ(x, y, 6, RED, "")
def alarm(x=100, y=112): return A("j", circ(x - 44, y - 54, 18, GOLD) + circ(x + 44, y - 54, 18, GOLD) + clockface(x, y, 54, 7, 0, WHITE, False) + line(x - 34, y + 50, x - 46, y + 66) + line(x + 34, y + 50, x + 46, y + 66))
def hourglass(x=100, y=104): return rect(x - 46, y - 74, 92, 12, BROWN, 4) + rect(x - 46, y + 62, 92, 12, BROWN, 4) + path(f"M{x - 34} {y - 62}L{x + 34} {y - 62}C{x + 34} {y - 20} {x + 6} {y - 10} {x + 6} {y}C{x + 6} {y + 10} {x + 34} {y + 20} {x + 34} {y + 62}L{x - 34} {y + 62}C{x - 34} {y + 20} {x - 6} {y + 10} {x - 6} {y}C{x - 6} {y - 10} {x - 34} {y - 20} {x - 34} {y - 62}Z", "#E4F4FF") + path(f"M{x - 22} {y - 40}L{x + 22} {y - 40}L{x} {y - 6}Z", GOLD, T) + path(f"M{x - 30} {y + 60}C{x - 20} {y + 30} {x + 20} {y + 30} {x + 30} {y + 60}Z", GOLD, T) + A("f", line(x, y, x, y + 20, f'stroke="{GOLD}" stroke-width="4"'))
def calendar(x=100, y=110, label="", sub="", c=RED, size=58, af=None):
    return rect(x - 64, y - 66, 128, 136, WHITE, 14) + path(f"M{x - 64} {y - 28}L{x - 64} {y - 52}Q{x - 64} {y - 66} {x - 50} {y - 66}L{x + 50} {y - 66}Q{x + 64} {y - 66} {x + 64} {y - 52}L{x + 64} {y - 28}Z", c) + rect(x - 34, y - 80, 12, 28, INK, 6, "") + rect(x + 22, y - 80, 12, 28, INK, 6, "") + (text(x, y + 34, label, size) if label else "") + (text(x, y + 58, sub, 18, "#6B7378") if sub else "") + (af or "")
def flag(x=100, y=100, c=RED, pole=True, cls="s"): return (line(x - 50, y - 70, x - 50, y + 80, f'stroke="{INK}" stroke-width="8" stroke-linecap="round"') if pole else "") + A(cls, path(f"M{x - 50} {y - 66}C{x - 20} {y - 80} {x + 10} {y - 50} {x + 56} {y - 64}L{x + 56} {y}C{x + 10} {y + 14} {x - 20} {y - 16} {x - 50} {y}Z", c), origin="0% 50%")
def tag(x=100, y=100, label="", c=YELLOW): return A("st", path(f"M{x - 60} {y - 30}L{x + 30} {y - 30}L{x + 64} {y}L{x + 30} {y + 30}L{x - 60} {y + 30}Z", c) + circ(x + 34, y, 7, WHITE, T) + text(x - 14, y + 13, label, 34), origin="90% 50%")
def coin(x, y, r=26, label=""): return circ(x, y, r, GOLD) + circ(x, y, r - 7, "none", T) + (text(x, y + r * .35, label, r * .9, "#8C6A14") if label else "")
def money(x=100, y=110): return A("b", rect(x - 70, y - 30, 120, 66, "#7FCF8A", 8) + circ(x - 10, y + 3, 16, "#5DBB63", T) + rect(x - 62, y - 22, 104, 50, "none", 5, T)) + coin(x + 50, y + 40, 24) + coin(x + 34, y + 6, 22)
def receipt(x=100, y=100): return path(f"M{x - 46} {y - 70}L{x + 46} {y - 70}L{x + 46} {y + 64}L{x + 30} {y + 54}L{x + 15} {y + 64}L{x} {y + 54}L{x - 15} {y + 64}L{x - 30} {y + 54}L{x - 46} {y + 64}Z", WHITE) + "".join(line(x - 30, y - 50 + k * 18, x + 30, y - 50 + k * 18, f'stroke="{GREY}" stroke-width="5" stroke-linecap="round"') for k in range(4)) + line(x - 30, y + 30, x + 30, y + 30, O)
def palette(x=100, y=104): return path(f"M{x - 10} {y - 66}C{x - 70} {y - 66} {x - 84} {y + 10} {x - 50} {y + 50}C{x - 20} {y + 80} {x + 60} {y + 70} {x + 76} {y + 20}C{x + 86} {y - 10} {x + 60} {y - 20} {x + 40} {y - 4}C{x + 20} {y + 10} {x + 20} {y - 30} {x + 40} {y - 40}C{x + 50} {y - 56} {x + 30} {y - 66} {x - 10} {y - 66}Z", "#F2D3A6") + "".join(circ(x + dx, y + dy, 11, c, T) for dx, dy, c in ((-40, -30, RED), (-52, 10, BLUE), (-30, 44, GREEN), (10, 50, YELLOW), (-6, -40, PURPLE)))
def splash(x=100, y=104, c=RED): return A("p", path(f"M{x} {y - 60}C{x + 20} {y - 40} {x + 30} {y - 60} {x + 44} {y - 40}C{x + 70} {y - 40} {x + 50} {y - 10} {x + 66} {y + 6}C{x + 60} {y + 30} {x + 40} {y + 20} {x + 36} {y + 46}C{x + 14} {y + 60} {x + 4} {y + 40} {x - 14} {y + 56}C{x - 36} {y + 56} {x - 30} {y + 30} {x - 56} {y + 30}C{x - 70} {y + 10} {x - 50} {y - 6} {x - 62} {y - 24}C{x - 56} {y - 50} {x - 30} {y - 30} {x - 26} {y - 56}C{x - 14} {y - 70} {x - 6} {y - 60} {x} {y - 60}Z", c)) + circ(x + 70, y - 56, 8, c) + circ(x - 66, y + 58, 6, c)

# ---- clothes -----------------------------------------------------------------------------------------------------------------
def shirt(x=100, y=110, c=BLUE): return path(f"M{x - 30} {y - 66}L{x - 74} {y - 44}L{x - 60} {y - 6}L{x - 42} {y - 14}L{x - 42} {y + 66}L{x + 42} {y + 66}L{x + 42} {y - 14}L{x + 60} {y - 6}L{x + 74} {y - 44}L{x + 30} {y - 66}C{x + 20} {y - 50} {x - 20} {y - 50} {x - 30} {y - 66}Z", c) + "".join(circ(x, y - 30 + k * 22, 3.5, WHITE, "") for k in range(4))
def thobe(x=100, y=104, c=WHITE): return path(f"M{x - 26} {y - 76}L{x - 66} {y - 56}L{x - 54} {y - 20}L{x - 40} {y - 26}L{x - 46} {y + 76}L{x + 46} {y + 76}L{x + 40} {y - 26}L{x + 54} {y - 20}L{x + 66} {y - 56}L{x + 26} {y - 76}C{x + 16} {y - 60} {x - 16} {y - 60} {x - 26} {y - 76}Z", c) + line(x, y - 62, x, y - 26, T)
def dress(x=100, y=104, c=PINK): return path(f"M{x - 22} {y - 76}L{x - 40} {y - 70}L{x - 34} {y - 36}L{x - 66} {y + 76}L{x + 66} {y + 76}L{x + 34} {y - 36}L{x + 40} {y - 70}L{x + 22} {y - 76}C{x + 14} {y - 62} {x - 14} {y - 62} {x - 22} {y - 76}Z", c) + path(f"M{x - 34} {y - 36}L{x + 34} {y - 36}", "none", T)
def coat(x=100, y=106): return path(f"M{x - 26} {y - 76}L{x - 70} {y - 54}L{x - 62} {y + 60}L{x - 44} {y + 60}L{x - 42} {y + 76}L{x + 42} {y + 76}L{x + 44} {y + 60}L{x + 62} {y + 60}L{x + 70} {y - 54}L{x + 26} {y - 76}L{x} {y - 30}Z", BROWN) + line(x, y - 30, x, y + 76, T) + "".join(circ(x + 10, y - 10 + k * 26, 4, INK, "") for k in range(3))
def hanger(x=100, y=60): return path(f"M{x - 8} {y - 26}C{x - 8} {y - 40} {x + 12} {y - 40} {x + 10} {y - 24}C{x + 8} {y - 14} {x} {y - 12} {x} {y}L{x - 66} {y + 36}L{x + 66} {y + 36}Z", "none")
def ihram(x=100, y=172): return person(x, y, .62, SKIN[1], None, WHITE, None, "#2a1d14") + path(f"M{x - 28} {y - 104}L{x + 28} {y - 70}", "none", f'stroke="{GREY}" stroke-width="4"')
def shoe(x=100, y=140): return path(f"M{x - 70} {y + 10}L{x - 66} {y - 40}L{x - 30} {y - 40}C{x - 20} {y - 10} {x + 20} {y - 10} {x + 50} {y - 6}C{x + 76} {y - 2} {x + 76} {y + 10} {x + 70} {y + 10}Z", RED) + rect(x - 72, y + 6, 146, 12, WHITE, 6)

# ---- home --------------------------------------------------------------------------------------------------------------------
def house(x=100, y=170, c="#FFD9A8", roof=RED, door=BROWN, w=120):
    return rect(x - w / 2, y - 90, w, 90, c, 4) + path(f"M{x - w / 2 - 14} {y - 86}L{x} {y - 150}L{x + w / 2 + 14} {y - 86}Z", roof) + rect(x - 16, y - 50, 32, 50, door, 4) + rect(x - w / 2 + 14, y - 72, 26, 24, "#CDEBFF", 3, T) + rect(x + w / 2 - 40, y - 72, 26, 24, "#CDEBFF", 3, T)
def flats(x=100, y=176, floors=4, hi=None):
    s = rect(x - 50, y - 30 * floors - 16, 100, 30 * floors + 16, "#C9B6E4", 4)
    for f in range(floors):
        for k in range(3): s += rect(x - 38 + k * 28, y - 30 * (f + 1) - 4, 20, 18, YELLOW if hi == f else "#CDEBFF", 3, T)
    return s
def door(x=100, y=172, open_=False): return rect(x - 50, y - 150, 100, 150, "#E8DCC8", 6) + (A("st", rect(x - 40, y - 140, 76, 140, BROWN, 4) + circ(x + 24, y - 70, 6, GOLD, T), origin="0% 50%") if open_ else rect(x - 40, y - 140, 80, 140, BROWN, 4) + circ(x + 24, y - 70, 6, GOLD, T))
def window(x=100, y=104): return rect(x - 60, y - 66, 120, 132, "#9FD8FF", 8) + line(x, y - 66, x, y + 66) + line(x - 60, y, x + 60, y) + A("x", cloud(x - 20, y - 30, .35))
def curtain(x=100, y=104): return rect(x - 70, y - 76, 140, 10, BROWN, 4) + rect(x - 54, y - 66, 108, 132, "#9FD8FF", 4) + A("s", path(f"M{x - 66} {y - 66}L{x - 20} {y - 66}C{x - 30} {y - 20} {x - 10} {y + 30} {x - 30} {y + 70}L{x - 66} {y + 70}Z", RED), origin="50% 0%") + A("s", path(f"M{x + 66} {y - 66}L{x + 20} {y - 66}C{x + 30} {y - 20} {x + 10} {y + 30} {x + 30} {y + 70}L{x + 66} {y + 70}Z", RED), d=1, origin="50% 0%")
def bed(x=100, y=150): return rect(x - 80, y - 60, 16, 90, BROWN, 6) + rect(x + 64, y - 30, 16, 60, BROWN, 6) + rect(x - 70, y - 20, 140, 30, WHITE, 6) + ell(x - 44, y - 30, 26, 14, WHITE) + path(f"M{x - 20} {y - 10}C{x - 20} {y - 40} {x + 70} {y - 40} {x + 70} {y - 10}Z", BLUE)
def pillow(x=100, y=110): return path(f"M{x - 70} {y - 40}C{x - 40} {y - 30} {x + 40} {y - 30} {x + 70} {y - 40}C{x + 60} {y - 10} {x + 60} {y + 10} {x + 70} {y + 40}C{x + 40} {y + 30} {x - 40} {y + 30} {x - 70} {y + 40}C{x - 60} {y + 10} {x - 60} {y - 10} {x - 70} {y - 40}Z", "#CFE5FF")
def rug(x=100, y=120, c=RED): return rect(x - 70, y - 50, 140, 100, c, 4) + rect(x - 56, y - 36, 112, 72, "none", 4, f'stroke="{YELLOW}" stroke-width="5"') + path(f"M{x} {y - 26}L{x + 30} {y}L{x} {y + 26}L{x - 30} {y}Z", YELLOW, T) + "".join(line(x - 70 + k * 14, y + 50, x - 70 + k * 14, y + 62, T) for k in range(11))
def prayermat(x=100, y=104, c=TEAL): return rect(x - 54, y - 74, 108, 148, c, 6) + path(f"M{x - 34} {y + 50}L{x - 34} {y - 24}C{x - 34} {y - 56} {x} {y - 64} {x} {y - 64}C{x} {y - 64} {x + 34} {y - 56} {x + 34} {y - 24}L{x + 34} {y + 50}Z", "none", f'stroke="{YELLOW}" stroke-width="5"') + rect(x - 54, y + 58, 108, 10, YELLOW, 2, T)
def sofa(x=100, y=150, c=PURPLE): return rect(x - 70, y - 70, 140, 50, c, 14) + rect(x - 84, y - 40, 28, 50, c, 10) + rect(x + 56, y - 40, 28, 50, c, 10) + rect(x - 58, y - 30, 116, 30, c, 8) + line(x - 70, y + 10, x - 70, y + 24) + line(x + 70, y + 10, x + 70, y + 24)
def chair(x=100, y=170): return rect(x - 30, y - 140, 60, 70, BROWN, 6) + rect(x - 40, y - 76, 80, 16, BROWN, 6) + line(x - 32, y - 60, x - 32, y) + line(x + 32, y - 60, x + 32, y)
def table(x=100, y=164): return rect(x - 80, y - 90, 160, 16, BROWN, 6) + line(x - 66, y - 74, x - 66, y) + line(x + 66, y - 74, x + 66, y)
def cupboard(x=100, y=172): return rect(x - 56, y - 150, 112, 150, "#C9935A", 6) + line(x, y - 150, x, y) + circ(x - 10, y - 76, 5, GOLD, T) + circ(x + 10, y - 76, 5, GOLD, T)
def fridge(x=100, y=172): return rect(x - 44, y - 156, 88, 156, WHITE, 12) + line(x - 44, y - 100, x + 44, y - 100) + line(x + 28, y - 140, x + 28, y - 116) + line(x + 28, y - 84, x + 28, y - 40) + A("g", snowflake(x - 14, y - 128, 12, "") )
def oven(x=100, y=168): return rect(x - 60, y - 130, 120, 130, GREY, 10) + rect(x - 44, y - 84, 88, 64, "#2B2F36", 6) + A("g", rect(x - 36, y - 76, 72, 48, ORANGE, 4, "")) + "".join(circ(x - 30 + k * 30, y - 108, 8, WHITE, T) for k in range(3))
def stove_pot(x=100, y=164): return rect(x - 70, y - 20, 140, 30, GREY, 8) + pot(x, y - 20, "#E8574B") + steam(x, y - 112)
def mirror(x=100, y=106): return ell(x, y, 54, 72, "#CDEBFF") + ell(x, y, 54, 72, "none", f'stroke="{GOLD}" stroke-width="10"') + A("x", path(f"M{x - 26} {y - 30}L{x - 4} {y - 52}M{x - 30} {y - 6}L{x + 10} {y - 46}", "none", f'stroke="#fff" stroke-width="7" stroke-linecap="round"'))
def lamp(x=100, y=172): return rect(x - 30, y - 10, 60, 10, BROWN, 4) + line(x, y - 10, x, y - 110) + path(f"M{x - 40} {y - 100}L{x - 24} {y - 150}L{x + 24} {y - 150}L{x + 40} {y - 100}Z", YELLOW)
def tub(x=100, y=150): return path(f"M{x - 80} {y - 40}L{x + 80} {y - 40}L{x + 70} {y + 10}C{x + 60} {y + 26} {x - 60} {y + 26} {x - 70} {y + 10}Z", WHITE) + path(f"M{x + 60} {y - 40}L{x + 60} {y - 110}L{x + 30} {y - 110}", "none") + "".join(A("r", circ(x + dx, y - 56 - dy, 9, "#CDEBFF", T), d=i) for i, (dx, dy) in enumerate(((-40, 0), (-14, 10), (10, 4))))
def vacuum(x=100, y=160): return rect(x - 70, y - 50, 70, 50, RED, 16) + circ(x - 56, y, 10, INK, "") + circ(x - 14, y, 10, INK, "") + path(f"M{x} {y - 30}C{x + 40} {y - 30} {x + 30} {y - 90} {x + 50} {y - 130}", "none", f'stroke="{INK}" stroke-width="9" stroke-linecap="round"') + A("x", path(f"M{x + 40} {y}L{x + 80} {y}", "none", f'stroke="{INK}" stroke-width="12" stroke-linecap="round"'))
def garden(x=100, y=170): return mini(flower(100, 174, PINK), x - 36, y - 56, .62) + mini(flower(100, 174, YELLOW), x + 30, y - 50, .56) + mini(tree(), x + 4, y - 80, .4) + "".join(line(x - 72 + k * 36, y, x - 72 + k * 36, y - 40, f'stroke="{BROWN}" stroke-width="8"') for k in range(5)) + line(x - 78, y - 28, x + 78, y - 28, f'stroke="{BROWN}" stroke-width="8"')
def bunting(x=100, y=60): return path(f"M{x - 86} {y}C{x - 30} {y + 30} {x + 30} {y + 30} {x + 86} {y}", "none", T) + "".join(A("st", path(f"M{x + dx - 12} {y + dy}L{x + dx + 12} {y + dy}L{x + dx} {y + dy + 26}Z", c, T), d=i % 3) for i, (dx, dy, c) in enumerate(((-60, 12, RED), (-30, 20, YELLOW), (0, 22, GREEN), (30, 20, BLUE), (60, 12, PINK))))
def lantern(x=100, y=104, glow=True): return line(x, y - 90, x, y - 60, T) + path(f"M{x - 20} {y - 60}L{x + 20} {y - 60}L{x + 26} {y - 44}L{x - 26} {y - 44}Z", GOLD) + path(f"M{x - 26} {y - 44}C{x - 44} {y} {x - 44} {y + 30} {x - 22} {y + 50}L{x + 22} {y + 50}C{x + 44} {y + 30} {x + 44} {y} {x + 26} {y - 44}Z", GOLD) + (A("g", path(f"M{x - 14} {y - 30}C{x - 26} {y} {x - 24} {y + 24} {x - 10} {y + 38}L{x + 10} {y + 38}C{x + 24} {y + 24} {x + 26} {y} {x + 14} {y - 30}Z", "#FFF1C9", T)) if glow else "") + rect(x - 18, y + 50, 36, 10, GOLD, 3)
def tent(x=100, y=168, c=ORANGE): return path(f"M{x - 80} {y}L{x} {y - 120}L{x + 80} {y}Z", c) + path(f"M{x} {y - 120}L{x - 20} {y}L{x + 20} {y}Z", "#8C4A1E") + line(x, y - 120, x, y - 140, T)
def hut(x=100, y=170): return rect(x - 56, y - 70, 112, 70, "#C9935A", 4) + path(f"M{x - 76} {y - 66}L{x} {y - 140}L{x + 76} {y - 66}Z", "#E2C26A") + "".join(line(x - 50 + k * 20, y - 80 + abs(k - 2.5) * 10, x - 60 + k * 24, y - 66, T) for k in range(6)) + rect(x - 16, y - 46, 32, 46, BROWN, 4)

# ---- places & transport ------------------------------------------------------------------------------------------------------
def car(x=100, y=140, c=RED): return A("b", path(f"M{x - 80} {y}L{x - 80} {y - 26}L{x - 50} {y - 30}L{x - 30} {y - 62}L{x + 30} {y - 62}L{x + 54} {y - 30}L{x + 80} {y - 24}L{x + 80} {y}Z", c) + path(f"M{x - 22} {y - 54}L{x - 6} {y - 54}L{x - 6} {y - 32}L{x - 38} {y - 32}Z", "#CDEBFF", T) + path(f"M{x + 6} {y - 54}L{x + 24} {y - 54}L{x + 42} {y - 32}L{x + 6} {y - 32}Z", "#CDEBFF", T)) + circ(x - 46, y + 4, 18, INK, "") + circ(x + 46, y + 4, 18, INK, "") + circ(x - 46, y + 4, 7, GREY, "") + circ(x + 46, y + 4, 7, GREY, "")
def bus(x=100, y=140): return A("b", rect(x - 84, y - 90, 168, 90, YELLOW, 14) + "".join(rect(x - 74 + k * 38, y - 78, 30, 30, "#CDEBFF", 4, T) for k in range(4)) + rect(x + 52, y - 40, 22, 30, "#CDEBFF", 4, T)) + circ(x - 50, y + 4, 16, INK, "") + circ(x + 50, y + 4, 16, INK, "")
def train(x=100, y=150): return A("x", rect(x - 84, y - 90, 140, 80, BLUE, 12) + path(f"M{x + 56} {y - 90}C{x + 84} {y - 90} {x + 92} {y - 50} {x + 92} {y - 10}L{x + 56} {y - 10}Z", BLUE) + "".join(rect(x - 74 + k * 36, y - 76, 26, 26, "#CDEBFF", 4, T) for k in range(4)) + "".join(circ(x - 60 + k * 50, y - 6, 12, INK, "") for k in range(4))) + line(x - 94, y + 10, x + 94, y + 10, f'stroke="{INK}" stroke-width="6" stroke-linecap="round"')
def plane(x=100, y=104, c=WHITE): return A("u", path(f"M{x - 80} {y + 6}C{x - 80} {y - 6} {x + 50} {y - 10} {x + 74} {y - 4}C{x + 90} {y} {x + 90} {y + 12} {x + 74} {y + 14}L{x - 80} {y + 18}Z", c) + path(f"M{x - 10} {y + 4}L{x - 40} {y + 60}L{x - 20} {y + 60}L{x + 30} {y + 8}Z", c) + path(f"M{x - 10} {y - 4}L{x - 30} {y - 46}L{x - 14} {y - 46}L{x + 20} {y - 6}Z", c) + path(f"M{x - 70} {y + 4}L{x - 84} {y - 30}L{x - 70} {y - 30}L{x - 52} {y + 2}Z", RED) + "".join(circ(x + 10 + k * 16, y + 4, 4, "#4D96FF", "") for k in range(4)))
def bike(x=100, y=140): return circ(x - 50, y, 30, "none") + circ(x + 50, y, 30, "none") + path(f"M{x - 50} {y}L{x - 14} {y - 50}L{x + 30} {y - 50}L{x + 50} {y}M{x - 14} {y - 50}L{x + 4} {y}L{x + 30} {y - 50}M{x - 22} {y - 62}L{x - 2} {y - 62}M{x + 30} {y - 50}L{x + 24} {y - 72}L{x + 40} {y - 72}", "none", f'stroke="{RED}" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"') + A("t", line(x - 50, y - 30, x - 50, y + 30, T)) + A("t", line(x + 50, y - 30, x + 50, y + 30, T))
def boat(x=100, y=150): return A("s", path(f"M{x - 70} {y - 20}L{x + 70} {y - 20}L{x + 50} {y + 16}L{x - 50} {y + 16}Z", BROWN) + line(x, y - 20, x, y - 140) + path(f"M{x + 6} {y - 136}L{x + 6} {y - 30}L{x + 70} {y - 30}Z", WHITE) + path(f"M{x - 6} {y - 120}L{x - 6} {y - 30}L{x - 56} {y - 30}Z", "#FFE08A")) + path(f"M{x - 90} {y + 24}q15 -12 30 0t30 0t30 0t30 0t30 0t30 0", "none", f'stroke="#4D96FF" stroke-width="7" stroke-linecap="round"')
def ambulance(x=100, y=146): return A("b", rect(x - 84, y - 90, 118, 84, WHITE, 8) + path(f"M{x + 34} {y - 66}L{x + 64} {y - 66}L{x + 84} {y - 40}L{x + 84} {y - 6}L{x + 34} {y - 6}Z", WHITE) + path(f"M{x - 34} {y - 66}L{x - 34} {y - 30}M{x - 52} {y - 48}L{x - 16} {y - 48}", "none", f'stroke="{RED}" stroke-width="12"') + rect(x + 44, y - 58, 26, 20, "#CDEBFF", 3, T)) + A("g", rect(x - 20, y - 104, 26, 14, RED, 4)) + circ(x - 50, y, 16, INK, "") + circ(x + 50, y, 16, INK, "")
def mosque(x=100, y=172, dome=GOLD, c=WHITE): return rect(x - 60, y - 70, 120, 70, c, 2) + path(f"M{x - 44} {y - 70}C{x - 44} {y - 140} {x + 44} {y - 140} {x + 44} {y - 70}Z", dome) + line(x, y - 124, x, y - 146, T) + moon(x + 3, y - 154, 9, YELLOW) + rect(x + 66, y - 150, 20, 150, c, 2) + path(f"M{x + 66} {y - 150}L{x + 76} {y - 176}L{x + 86} {y - 150}Z", dome) + path(f"M{x - 16} {y}L{x - 16} {y - 34}C{x - 16} {y - 52} {x + 16} {y - 52} {x + 16} {y - 34}L{x + 16} {y}Z", TEAL)
def kaaba(x=100, y=164, s=1.0): return f'<g transform="translate({x},{y}) scale({s})">' + path("M-60 0L-60 -90L0 -110L60 -90L60 0L0 14Z", "#1E1E1E") + path("M-60 -90L0 -110L60 -90L0 -72Z", "#2B2B2B") + path("M-60 -70L0 -52L60 -70L60 -58L0 -40L-60 -58Z", GOLD, T) + rect(14, -40, 18, 34, GOLD, 3, T) + "</g>"
def minaret(x=100, y=176, c=WHITE): return rect(x - 18, y - 130, 36, 130, c, 2) + rect(x - 28, y - 110, 56, 12, c, 4) + path(f"M{x - 18} {y - 130}L{x} {y - 166}L{x + 18} {y - 130}Z", GOLD) + moon(x + 2, y - 176, 7, YELLOW)
def greendome(x=100, y=172): return rect(x - 66, y - 60, 132, 60, "#F4EBD9", 2) + path(f"M{x - 44} {y - 60}C{x - 44} {y - 136} {x + 44} {y - 136} {x + 44} {y - 60}Z", "#2E9A5E") + line(x, y - 118, x, y - 140, T) + moon(x + 3, y - 148, 9, YELLOW) + rect(x - 88, y - 140, 18, 140, "#F4EBD9", 2) + path(f"M{x - 88} {y - 140}L{x - 79} {y - 160}L{x - 70} {y - 140}Z", "#2E9A5E")
def church(x=100, y=172): return rect(x - 50, y - 90, 100, 90, "#F4EBD9", 2) + path(f"M{x - 60} {y - 86}L{x} {y - 140}L{x + 60} {y - 86}Z", "#8E9BA6") + path(f"M{x} {y - 140}L{x} {y - 176}M{x - 12} {y - 164}L{x + 12} {y - 164}", "none", f'stroke="{INK}" stroke-width="7" stroke-linecap="round"') + path(f"M{x - 14} {y}L{x - 14} {y - 34}C{x - 14} {y - 50} {x + 14} {y - 50} {x + 14} {y - 34}L{x + 14} {y}Z", BROWN)
def building(x=100, y=176, c="#9FB4C8", w=96, h=140, sign=""): return rect(x - w / 2, y - h, w, h, c, 4) + "".join(rect(x - w / 2 + 12 + i * 28, y - h + 16 + j * 30, 18, 18, "#E4F4FF", 3, T) for i in range(int((w - 16) // 28)) for j in range(int((h - 40) // 30))) + rect(x - 14, y - 30, 28, 30, BROWN, 3) + sign
def school(x=100, y=172): return rect(x - 70, y - 80, 140, 80, "#FFD9A8", 2) + path(f"M{x - 80} {y - 76}L{x} {y - 128}L{x + 80} {y - 76}Z", RED) + circ(x, y - 96, 13, WHITE) + line(x, y - 96, x + 6, y - 102, T) + rect(x - 14, y - 40, 28, 40, BROWN, 3) + "".join(rect(x + dx, y - 64, 22, 20, "#CDEBFF", 3, T) for dx in (-58, -32, 10, 36)) + mini(flag(), x + 58, y - 106, .36)
def university(x=100, y=172): return path(f"M{x - 86} {y - 100}L{x} {y - 146}L{x + 86} {y - 100}Z", "#E8DCC8") + rect(x - 80, y - 100, 160, 14, "#E8DCC8", 2) + "".join(rect(x - 70 + k * 36, y - 86, 16, 76, WHITE, 2) for k in range(5)) + rect(x - 86, y - 14, 172, 14, "#E8DCC8", 2)
def hospital(x=100, y=172): return building(x, y, "#F4F6F8", 110, 140) + rect(x - 22, y - 168, 44, 44, RED, 8) + path(f"M{x} {y - 160}L{x} {y - 132}M{x - 14} {y - 146}L{x + 14} {y - 146}", "none", f'stroke="#fff" stroke-width="9" stroke-linecap="round"')
def shop(x=100, y=172): return rect(x - 70, y - 70, 140, 70, "#FFD9A8", 2) + "".join(path(f"M{x - 76 + k * 38} {y - 110}L{x - 38 + k * 38} {y - 110}L{x - 38 + k * 38} {y - 84}C{x - 38 + k * 38} {y - 70} {x - 76 + k * 38} {y - 70} {x - 76 + k * 38} {y - 84}Z", RED if k % 2 == 0 else WHITE) for k in range(4)) + rect(x - 54, y - 56, 46, 34, "#CDEBFF", 3, T) + rect(x + 10, y - 56, 34, 56, BROWN, 3)
def stall(x=100, y=170): return path(f"M{x - 86} {y - 120}L{x + 86} {y - 120}L{x + 76} {y - 90}L{x - 76} {y - 90}Z", ORANGE) + line(x - 70, y - 90, x - 70, y) + line(x + 70, y - 90, x + 70, y) + rect(x - 76, y - 50, 152, 20, BROWN, 4) + "".join(circ(x + dx, y - 60, 12, c, T) for dx, c in ((-50, RED), (-26, ORANGE), (0, GREEN), (24, YELLOW), (48, RED)))
def city(x=100, y=176, star_=False): return "".join(rect(x + dx, y - h, 32, h, c, 3) + "".join(rect(x + dx + 8, y - h + 10 + j * 22, 16, 10, YELLOW, 2, "") for j in range(int((h - 20) // 22))) for dx, h, c in ((-84, 90, "#9FB4C8"), (-50, 130, "#8296AE"), (-16, 110, "#9FB4C8"), (18, 150, "#6E86A3"), (52, 100, "#8296AE"))) + (A("p", star(x + 34, y - 168, 14)) if star_ else "")
def village(x=100, y=172): return house(x - 46, y, "#FFE3B8", RED, BROWN, 64) + house(x + 40, y + 4, "#E8DCC8", ORANGE, BROWN, 72) + tree(x + 80, y, .45)
def barn(x=100, y=172): return rect(x - 66, y - 90, 132, 90, RED, 2) + path(f"M{x - 76} {y - 86}L{x - 50} {y - 130}L{x + 50} {y - 130}L{x + 76} {y - 86}Z", "#9C2F27") + rect(x - 26, y - 56, 52, 56, WHITE, 2) + path(f"M{x - 26} {y - 56}L{x + 26} {y}M{x + 26} {y - 56}L{x - 26} {y}", "none", T)
def pin(x=100, y=100, c=RED): return A("h", path(f"M{x} {y + 50}C{x - 20} {y + 20} {x - 40} {y} {x - 40} {y - 24}C{x - 40} {y - 50} {x - 20} {y - 66} {x} {y - 66}C{x + 20} {y - 66} {x + 40} {y - 50} {x + 40} {y - 24}C{x + 40} {y} {x + 20} {y + 20} {x} {y + 50}Z", c) + circ(x, y - 26, 14, WHITE)) + ell(x, y + 62, 30, 7, "#00000022", "")
def compass(x=100, y=104, n="N"):
    pos = {"N": (0, -1), "S": (0, 1), "E": (1, 0), "W": (-1, 0)}[n]
    return circ(x, y, 70, WHITE) + "".join(text(x + 52 * dx, y + 52 * dy + 8, l, 22, RED if l == n else INK) for l, (dx, dy) in (("N", (0, -1)), ("S", (0, 1)), ("E", (1, 0)), ("W", (-1, 0)))) + A("j", path(f"M{x + 40 * pos[0]} {y + 40 * pos[1]}L{x + 10 * pos[1]} {y - 10 * pos[0]}L{x - 40 * pos[0]} {y - 40 * pos[1]}L{x - 10 * pos[1]} {y + 10 * pos[0]}Z", RED, T)) + circ(x, y, 6, INK, "")
def crowd(x=100, y=176, n=5): return "".join(person(x + dx, y + dy, .34, SKIN[k % 5], ["kufi", "hijab:#9B6BFF", "hair:#3a2a1c", "hijab:#2EB67D", "cap:#4D96FF"][k % 5], [BLUE, PINK, ORANGE, YELLOW, TEAL][k % 5]) for k, (dx, dy) in enumerate([(-64, 0), (-32, -8), (0, 2), (32, -6), (64, 2), (-48, 10), (16, 12), (48, 14)][:n]))
def museum(x=100, y=172): return path(f"M{x - 84} {y - 110}L{x} {y - 150}L{x + 84} {y - 110}Z", "#E8DCC8") + rect(x - 80, y - 110, 160, 12, "#E8DCC8", 2) + "".join(rect(x - 66 + k * 30, y - 96, 14, 84, WHITE, 2) for k in range(5)) + rect(x - 84, y - 14, 168, 14, "#E8DCC8", 2) + circ(x, y - 126, 8, GOLD, T)
def easel(x=100, y=176): return line(x - 50, y, x, y - 150) + line(x + 50, y, x, y - 150) + rect(x - 56, y - 130, 112, 84, WHITE, 4) + A("p", circ(x - 20, y - 96, 14, YELLOW, T)) + path(f"M{x - 46} {y - 54}L{x - 10} {y - 86}L{x + 16} {y - 64}L{x + 30} {y - 76}L{x + 48} {y - 54}Z", GREEN, T)
def frames(x=100, y=104): return rect(x - 84, y - 50, 70, 54, "#F4EBD9", 4) + A("p", sun(x - 49, y - 23, 12, False)) + rect(x + 6, y - 66, 76, 90, "#F4EBD9", 4) + path(f"M{x + 14} {y + 14}L{x + 34} {y - 20}L{x + 50} {y}L{x + 60} {y - 12}L{x + 74} {y + 14}Z", GREEN, T) + rect(x - 60, y + 20, 50, 46, "#F4EBD9", 4) + circ(x - 35, y + 43, 12, PINK, T)

# ---- study, work, maths ------------------------------------------------------------------------------------------------------
def board(x=100, y=100, inner=""): return rect(x - 80, y - 60, 160, 110, "#2E6B4E", 8) + rect(x - 80, y - 60, 160, 110, "none", 8, f'stroke="{BROWN}" stroke-width="8"') + inner + rect(x - 30, y + 50, 60, 8, BROWN, 3, T)
def flask(x=100, y=150, c=GREEN): return path(f"M{x - 16} {y - 110}L{x - 16} {y - 60}L{x - 56} {y}L{x + 56} {y}L{x + 16} {y - 60}L{x + 16} {y - 110}Z", "#E4F4FF") + path(f"M{x - 40} {y - 22}L{x + 40} {y - 22}L{x + 56} {y}L{x - 56} {y}Z", c, "") + rect(x - 22, y - 120, 44, 12, GREY, 4) + "".join(A("r", circ(x + dx, y - 40 - dy, 6, c, T), d=i) for i, (dx, dy) in enumerate(((-8, 0), (10, 14), (0, 28))))
def gear(x=100, y=104, r=44, c=GREY, cls="t"):
    import math
    teeth = "".join(rect(x - 9, y - r - 14, 18, 22, c, 3, "").replace('<rect', f'<rect transform="rotate({a} {x} {y})"') for a in range(0, 360, 45))
    return A(cls, teeth + circ(x, y, r, c) + circ(x, y, r * .38, WHITE))
def helmet(x=100, y=120, c=YELLOW): return path(f"M{x - 70} {y + 10}C{x - 70} {y - 60} {x + 70} {y - 60} {x + 70} {y + 10}Z", c) + rect(x - 84, y, 168, 18, c, 8) + rect(x - 10, y - 56, 20, 50, "#E8B020", 4, T)
def toolbox(x=100, y=130): return rect(x - 70, y - 40, 140, 70, RED, 8) + path(f"M{x - 30} {y - 40}L{x - 30} {y - 62}L{x + 30} {y - 62}L{x + 30} {y - 40}", "none") + line(x - 70, y - 14, x + 70, y - 14, T)
def mic(x=100, y=100): return rect(x - 22, y - 70, 44, 76, "#2B2F36", 22) + path(f"M{x - 38} {y - 10}C{x - 38} {y + 34} {x + 38} {y + 34} {x + 38} {y - 10}", "none") + line(x, y + 24, x, y + 54) + line(x - 26, y + 54, x + 26, y + 54)
def printer(x=100, y=130): return rect(x - 50, y - 80, 100, 40, WHITE, 4) + rect(x - 70, y - 44, 140, 56, GREY, 8) + A("u", paper(x, y + 30, 80, 40, 1)) + circ(x + 50, y - 26, 5, GREEN, "")
def magazine(x=100, y=104): return rect(x - 50, y - 70, 100, 140, PINK, 6) + text(x, y - 34, "MAG", 26, WHITE) + circ(x, y + 14, 26, YELLOW, T) + rect(x - 34, y + 48, 68, 8, WHITE, 3, "")
def dictionary(x=100, y=106, c="#8C2F39"): return closedbook(x, y, c, text(x, y - 18, "أ - ي", 26, WHITE, "IBM Plex Sans Arabic, Arial")) + rect(x - 50, y - 64, 14, 112, "#6E2430", 4, "")
def chart(x=100, y=150): return line(x - 70, y, x + 70, y) + line(x - 70, y, x - 70, y - 120) + "".join(A("k", rect(x - 56 + k * 34, y - h, 22, h, c, 3, T), d=k) for k, (h, c) in enumerate(((40, BLUE), (70, GREEN), (55, ORANGE), (100, RED))))
def mathsigns(x=100, y=104): return text(x - 36, y - 10, "+", 64, RED) + text(x + 36, y - 10, "−", 64, BLUE) + text(x - 36, y + 56, "×", 64, GREEN) + text(x + 36, y + 56, "÷", 64, PURPLE)
def stairs(x=100, y=164, hi=1): return "".join(rect(x - 80 + k * 40, y - 40 * (k + 1), 40, 40 * (k + 1), YELLOW if k == hi else "#E8DCC8", 2) for k in range(4)) + (A("h", circ(x - 60 + hi * 40, y - 40 * (hi + 1) - 16, 12, RED)) if hi is not None else "")
def calligraphy(x=100, y=104, s="ن"): return rect(x - 70, y - 60, 140, 110, "#FFF8EC", 8) + ar(x - 6, y + 26, s, 80, "#1E3A5F") + A("c", path(f"M{x + 34} {y - 60}L{x + 74} {y - 100}L{x + 84} {y - 90}L{x + 44} {y - 50}Z", BROWN) + path(f"M{x + 34} {y - 60}L{x + 28} {y - 44}L{x + 44} {y - 50}Z", INK, T))
def sewing(x=100, y=104): return needle(x - 10, y - 4) + ell(x - 30, y + 50, 30, 18, RED) + line(x - 60, y + 50, x, y + 50, T)
def trophy(x=100, y=164): return rect(x - 40, y - 20, 80, 20, BROWN, 4) + rect(x - 10, y - 50, 20, 30, GOLD, 2) + path(f"M{x - 44} {y - 140}L{x + 44} {y - 140}C{x + 44} {y - 80} {x + 20} {y - 54} {x} {y - 54}C{x - 20} {y - 54} {x - 44} {y - 80} {x - 44} {y - 140}Z", GOLD) + path(f"M{x - 44} {y - 128}C{x - 76} {y - 128} {x - 70} {y - 90} {x - 36} {y - 90}M{x + 44} {y - 128}C{x + 76} {y - 128} {x + 70} {y - 90} {x + 36} {y - 90}", "none") + A("g", star(x, y - 104, 14, WHITE, T))
def medal(x=100, y=110, label="1", c=GOLD): return path(f"M{x - 40} {y - 90}L{x - 14} {y - 30}L{x + 14} {y - 30}L{x + 40} {y - 90}L{x + 20} {y - 90}L{x} {y - 50}L{x - 20} {y - 90}Z", BLUE) + A("j", circ(x, y + 10, 48, c) + circ(x, y + 10, 36, "none", T) + text(x, y + 28, label, 46, "#7A5A10"))
def no_sign(x=100, y=104): return circ(x, y, 64, WHITE, f'stroke="{RED}" stroke-width="16"') + line(x - 44, y + 44, x + 44, y - 44, f'stroke="{RED}" stroke-width="16"')
def idea(): return bulb(100, 92)
def oud(x=100, y=110): return A("s", path(f"M{x - 10} {y + 70}C{x - 70} {y + 70} {x - 70} {y - 10} {x - 20} {y - 20}C{x + 10} {y - 26} {x + 40} {y + 10} {x + 40} {y + 30}C{x + 40} {y + 56} {x + 20} {y + 70} {x - 10} {y + 70}Z", "#B5652A") + circ(x - 16, y + 24, 12, "#5A3214", T) + path(f"M{x + 10} {y - 10}L{x + 70} {y - 76}", "none", f'stroke="{INK}" stroke-width="14" stroke-linecap="round"') + path(f"M{x + 64} {y - 70}L{x + 84} {y - 72}", "none", O))
def flute(x=100, y=104): return A("s", path(f"M{x - 70} {y + 50}L{x + 60} {y - 50}", "none", f'stroke="{INK}" stroke-width="22" stroke-linecap="round"') + path(f"M{x - 70} {y + 50}L{x + 60} {y - 50}", "none", f'stroke="#D9A55B" stroke-width="13" stroke-linecap="round"') + "".join(circ(x - 30 + k * 18, y + 20 - k * 14, 3.5, INK, "") for k in range(5))) + A("g", text(x + 60, y + 10, "♪", 40, PURPLE))

