def quran(x=100, y=150, c="#1F6B4A"): return path(f"M{x - 70} {y}L{x} {y - 40}L{x + 70} {y}L{x + 58} {y + 10}L{x} {y - 22}L{x - 58} {y + 10}Z", BROWN) + path(f"M{x} {y - 40}C{x - 24} {y - 66} {x - 56} {y - 66} {x - 70} {y - 56}L{x - 70} {y}C{x - 50} {y - 14} {x - 20} {y - 14} {x} {y - 40}Z", c) + path(f"M{x} {y - 40}C{x + 24} {y - 66} {x + 56} {y - 66} {x + 70} {y - 56}L{x + 70} {y}C{x + 50} {y - 14} {x + 20} {y - 14} {x} {y - 40}Z", c) + path(f"M{x} {y - 44}C{x - 22} {y - 72} {x - 50} {y - 78} {x - 62} {y - 70}L{x - 62} {y - 14}C{x - 46} {y - 22} {x - 22} {y - 18} {x} {y - 44}Z", "#FFF8EC") + path(f"M{x} {y - 44}C{x + 22} {y - 72} {x + 50} {y - 78} {x + 62} {y - 70}L{x + 62} {y - 14}C{x + 46} {y - 22} {x + 22} {y - 18} {x} {y - 44}Z", "#FFF8EC") + "".join(path(f"M{x + d * 14} {y - 56 + k * 10}L{x + d * 50} {y - 62 + k * 10}", "none", f'stroke="{GOLD}" stroke-width="3.5" stroke-linecap="round"') for d in (-1, 1) for k in range(3))
def mushaf(x=100, y=104, c="#1F6B4A"): return rect(x - 52, y - 70, 104, 140, c, 10) + rect(x - 40, y - 58, 80, 116, "none", 6, f'stroke="{GOLD}" stroke-width="5"') + path(f"M{x} {y - 30}L{x + 26} {y}L{x} {y + 30}L{x - 26} {y}Z", GOLD, T)
def beads(x=100, y=100): return "".join(circ(x + 50 * __import__('math').cos(t / 16 * 6.283), y - 10 + 40 * __import__('math').sin(t / 16 * 6.283), 9, TEAL, T) for t in range(16)) + A("st", line(x, y + 30, x, y + 66, T) + circ(x, y + 72, 10, GOLD, T))
def crescent_star(x=100, y=100): return moon(x - 6, y, 56, YELLOW) + A("p", star(x + 40, y - 16, 18, YELLOW))
def hands_dua(x=100, y=118): return hand(x - 28, y, SKIN[1], .9).replace('<g transform', '<g transform', 1) + f'<g transform="translate({x + 28},{y}) scale(-.9,.9)">' + path("M-34 60L-38 0C-40 -10 -26 -12 -24 0L-24 -50C-24 -62 -8 -62 -8 -50L-8 -62C-8 -74 8 -74 8 -62L8 -54C8 -66 24 -66 24 -54L24 -40C24 -50 38 -50 38 -40L38 20C38 44 26 60 14 60Z", SKIN[1]) + "</g>" + sparks((100, 30, 9), (40, 50, 7), (160, 50, 7))
def tap_water(x=100, y=72): return rect(x - 70, y - 20, 90, 24, GREY, 8) + rect(x + 10, y - 20, 24, 50, GREY, 8) + rect(x - 60, y - 40, 20, 24, RED, 6) + "".join(A("f", path(f"M{x + 22} {y + 40}c-6 10 -6 16 0 18c6 -2 6 -8 0 -18z", "#4D96FF", T), d=i) for i in range(3)) + hand(x + 20, y + 84, SKIN[1], .6)
def pillars(x=100, y=160): return rect(x - 70, y - 90, 26, 90, "#C9B08A", 4) + rect(x + 44, y - 90, 26, 90, "#C9B08A", 4) + ell(x - 57, y - 92, 20, 8, "#C9B08A") + ell(x + 57, y - 92, 20, 8, "#C9B08A") + "".join(circ(x + dx, y + dy, 6, "#8E9BA6", T) for dx, dy in ((-20, -4), (0, 4), (20, -2), (-6, -12), (12, -14)))
def hill(x=100, y=160, label=""): return path(f"M{x - 80} {y}C{x - 40} {y - 90} {x + 40} {y - 90} {x + 80} {y}Z", "#C9B08A") + (text(x, y - 24, label, 22) if label else "")
def safa_marwa(x=100, y=160): return path(f"M{x - 94} {y}C{x - 80} {y - 60} {x - 40} {y - 60} {x - 30} {y}Z", "#C9B08A") + path(f"M{x + 30} {y}C{x + 40} {y - 60} {x + 80} {y - 60} {x + 94} {y}Z", "#C9B08A") + A("x", person(x - 40, y - 4, .3, SKIN[1], None, WHITE)) + path(f"M{x - 30} {y + 10}L{x + 30} {y + 10}", "none", f'stroke="{INK}" stroke-width="4" stroke-dasharray="6 8"')
def circuit(x=100, y=104, inner=""): return inner + A("t", f'<circle cx="{x}" cy="{y}" r="74" fill="none"/>' + path(f"M{x + 74} {y}A74 74 0 1 1 {x + 52} {y - 52}", "none", f'stroke="{TEAL}" stroke-width="8" stroke-linecap="round"') + path(f"M{x + 40} {y - 64}L{x + 60} {y - 44}L{x + 34} {y - 36}Z", TEAL, ""))
def jabal(x=100, y=168): return path(f"M{x - 90} {y}C{x - 50} {y - 40} {x - 30} {y - 90} {x} {y - 96}C{x + 30} {y - 90} {x + 50} {y - 40} {x + 90} {y}Z", "#B59A72") + rect(x - 4, y - 130, 8, 36, WHITE, 2) + sun(x + 50, y - 114, 15)
